/* I Am an Heir (Grown-ups) — blessed adult declaration library (386), KJV-verified. Generated. */
window.HEIR_DECLS=[{"id":"1-peter-1-3","ref":"1 Peter 1:3","kjv":"Blessed be the God and Father of our Lord Jesus Christ, which according to his abundant mercy hath begotten us again unto a lively hope by the resurrection of Jesus Christ from the dead,","say":"Blessed be God, who according to His abundant mercy has begotten me again unto a lively hope by the resurrection of Jesus Christ from the dead.","theme":"comfort-hope","when":"facing loss or hopelessness","mean":"My new birth rests on Christ's resurrection, giving me a living hope that outlasts any loss, so I press on anchored in His risen life."},{"id":"2-corinthians-1-3","ref":"2 Corinthians 1:3","kjv":"Blessed be God, even the Father of our Lord Jesus Christ, the Father of mercies, and the God of all comfort;","say":"The God of all comfort is my Father, the Father of mercies, and He comforts me in all my tribulation.","theme":"comfort-hope","when":"grieving","mean":"Comfort is part of who God is as my Father, so I can run to Him in any grief and receive real consolation."},{"id":"isaiah-43-19","ref":"Isaiah 43:19","kjv":"Behold, I will do a new thing; now it shall spring forth; shall ye not know it? I will even make a way in the wilderness, and rivers in the desert.","say":"Behold, God is doing a new thing; now it springs forth. He makes a way for me in the wilderness, and rivers in my desert.","theme":"comfort-hope","when":"stuck in a dry season","mean":"God is not finished; even in barren places He pioneers fresh life and provision, so I watch expectantly for what He is bringing forth."},{"id":"jeremiah-29-11","ref":"Jeremiah 29:11","kjv":"For I know the thoughts that I think toward you, saith the LORD, thoughts of peace, and not of evil, to give you an expected end.","say":"God's thoughts toward me are thoughts of peace and not of evil, to give me hope and an expected end; my future rests in His good intentions.","theme":"comfort-hope","when":"uncertain about the future","mean":"God's heart toward His people is peace and hope, so I can trust His good intentions even when my own plans are shaken."},{"id":"lamentations-3-23","ref":"Lamentations 3:23","kjv":"They are new every morning: great is thy faithfulness.","say":"God's mercies toward me are new every morning; great is His faithfulness.","theme":"comfort-hope","when":"need fresh mercy","mean":"Every sunrise brings a fresh supply of God's mercy, so yesterday's failures and sorrows do not disqualify today."},{"id":"psalm-147-3","ref":"Psalms 147:3","kjv":"He healeth the broken in heart, and bindeth up their wounds.","say":"God heals my broken heart and binds up every wound, for He is tender toward the hurting.","theme":"comfort-hope","when":"heartbroken","mean":"The same God who numbers the stars stoops to mend broken hearts, so no wound of mine is too deep for His healing."},{"id":"psalm-30-5","ref":"Psalms 30:5","kjv":"For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.","say":"My weeping may endure for a night, but God's joy comes to me in the morning.","theme":"comfort-hope","when":"in a dark season","mean":"Grief is real but it is not the final word; God has appointed a morning of joy beyond the night, so I hold on."},{"id":"psalm-34-18","ref":"Psalms 34:18","kjv":"The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.","say":"The Lord is near to me when my heart is broken, and He saves me, for my spirit is contrite before Him.","theme":"comfort-hope","when":"crushed","mean":"God draws closest exactly when I feel most crushed, so brokenness becomes the place I meet His saving nearness rather than His distance."},{"id":"psalm-42-11","ref":"Psalms 42:11","kjv":"Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God.","say":"I will not stay cast down; I hope in God, for I shall yet praise Him, the health of my countenance and my God.","theme":"comfort-hope","when":"downcast","mean":"I can preach to my own downcast soul, redirecting it from despair to hope in God, confident I will praise Him again."},{"id":"revelation-21-4","ref":"Revelation 21:4","kjv":"And God shall wipe away all tears from their eyes; and there shall be no more death, neither sorrow, nor crying, neither shall there be any more pain: for the former things are passed away.","say":"God Himself shall wipe away all my tears, and there shall be no more death, sorrow, crying, or pain.","theme":"comfort-hope","when":"grief and loss","mean":"My present sorrows have an expiry date because God will personally wipe away every tear in a future free of death and pain."},{"id":"romans-5-5","ref":"Romans 5:5","kjv":"And hope maketh not ashamed; because the love of God is shed abroad in our hearts by the Holy Ghost which is given unto us.","say":"My hope in God will never put me to shame, for His love is shed abroad in my heart by the Holy Ghost.","theme":"comfort-hope","when":"disappointed hope","mean":"Hope rooted in God never ends in disappointment because it rests on His proven love poured in by the Spirit, not on circumstances."},{"id":"2-chronicles-20-20","ref":"2 Chronicles 20:20","kjv":"And they rose early in the morning, and went forth into the wilderness of Tekoa: and as they went forth, Jehoshaphat stood and said, Hear me, O Judah, and ye inhabitants of Jerusalem; Believe in the LORD your God, so shall ye be established; believe his prophets, so shall ye prosper.","say":"I believe in the LORD my God, so I shall be established; I believe His word, so I shall be sustained.","theme":"faith-trust","when":"facing opposition","mean":"Settled faith in God and His word is what steadies and carries me when I face a battle I cannot fight alone."},{"id":"2-corinthians-5-7","ref":"2 Corinthians 5:7","kjv":"(For we walk by faith, not by sight:)","say":"I walk by faith and not by sight; what I cannot yet see does not govern how I live.","theme":"faith-trust","when":"can't see the way forward","mean":"My conduct is directed by God's word and promises rather than by appearances, so present uncertainty does not stop my obedience."},{"id":"exodus-14-14","ref":"Exodus 14:14","kjv":"The LORD shall fight for you, and ye shall hold your peace.","say":"The LORD shall fight for me, and I shall hold my peace.","theme":"faith-trust","when":"trapped, no way out","mean":"At the dead end where I can do nothing, my part is to stop striving and trust while the LORD Himself fights, so stillness becomes an act of faith rather than defeat."},{"id":"habakkuk-2-4","ref":"Habakkuk 2:4","kjv":"Behold, his soul which is lifted up is not upright in him: but the just shall live by his faith.","say":"I am counted among the just, and I live by my faith, day after day.","theme":"faith-trust","when":"daily endurance","mean":"Faith is not only for crises but the steady, ongoing way the righteous live before God."},{"id":"hebrews-11-1","ref":"Hebrews 11:1","kjv":"Now faith is the substance of things hoped for, the evidence of things not seen.","say":"My faith is the substance of what I hope for and the evidence of what I cannot yet see.","theme":"faith-trust","when":"holding an unseen promise","mean":"Faith gives present substance and assurance to God's promises before they become visible to my eyes."},{"id":"hebrews-11-6","ref":"Hebrews 11:6","kjv":"But without faith it is impossible to please him: for he that cometh to God must believe that he is, and that he is a rewarder of them that diligently seek him.","say":"I come to God believing that He is, and that He rewards those who diligently seek Him; and by faith I please my Father.","theme":"faith-trust","when":"drawing near to God","mean":"Faith is the non-negotiable way I approach God, trusting both that He exists and that He answers those who earnestly seek Him."},{"id":"jeremiah-17-7","ref":"Jeremiah 17:7","kjv":"Blessed is the man that trusteth in the LORD, and whose hope the LORD is.","say":"I am blessed because I trust in the LORD, and the LORD Himself is my hope.","theme":"faith-trust","when":"where to place my hope","mean":"Real blessing rests on making God, not people or circumstances, the anchor of my confidence."},{"id":"mark-9-23","ref":"Mark 9:23","kjv":"Jesus said unto him, If thou canst believe, all things are possible to him that believeth.","say":"If I can believe, all things are possible to the one who believes; so I choose to believe my God.","theme":"faith-trust","when":"facing the impossible","mean":"Jesus ties the realm of the possible to believing trust in Him, so I bring even my hardest situation to Him in faith."},{"id":"matthew-9-29","ref":"Matthew 9:29","kjv":"Then touched he their eyes, saying, According to your faith be it unto you.","say":"Lord, according to my faith be it unto me; I open my heart to believe You for what You have said.","theme":"faith-trust","when":"stretching my faith","mean":"Jesus responds to believing faith, so I come to Him actively trusting His word rather than wavering in doubt."},{"id":"psalm-125-1","ref":"Psalms 125:1","kjv":"They that trust in the LORD shall be as mount Zion, which cannot be removed, but abideth for ever.","say":"Because I trust in the LORD, I am as mount Zion, which cannot be removed, but abideth for ever.","theme":"faith-trust","when":"feeling shaken","mean":"Trusting God gives me a stability that outside pressures cannot topple."},{"id":"psalm-37-5","ref":"Psalms 37:5","kjv":"Commit thy way unto the LORD; trust also in him; and he shall bring it to pass.","say":"I commit my way unto the LORD; I trust also in Him, and He shall bring it to pass.","theme":"faith-trust","when":"waiting on an outcome","mean":"I hand God my plans and release the result to Him, confident He will act in His own time."},{"id":"psalm-56-3","ref":"Psalms 56:3","kjv":"What time I am afraid, I will trust in thee.","say":"What time I am afraid, I will trust in Thee.","theme":"faith-trust","when":"afraid","mean":"Fear becomes a trigger to turn to God rather than a reason to retreat, an honest choice to trust Him in the very moment of dread."},{"id":"romans-10-17","ref":"Romans 10:17","kjv":"So then faith cometh by hearing, and hearing by the word of God.","say":"Faith comes to me by hearing, and hearing by the word of God; so I feed my faith on His word.","theme":"faith-trust","when":"faith feels weak","mean":"I grow my faith deliberately by taking in God's word, since that is where faith is born and strengthened."},{"id":"1-john-4-16","ref":"1 John 4:16","kjv":"And we have known and believed the love that God hath to us. God is love; and he that dwelleth in love dwelleth in God, and God in him.","say":"I have known and believed the love God has for me. God is love, and as I dwell in love I dwell in God, and God in me.","theme":"gods-love","when":"needing assurance","mean":"Love is who God is and not merely what He does, so as I rest in His love I am abiding in God Himself."},{"id":"ephesians-3-19","ref":"Ephesians 3:19","kjv":"And to know the love of Christ, which passeth knowledge, that ye might be filled with all the fulness of God.","say":"I know the love of Christ which passes knowledge, and I am filled with all the fulness of God.","theme":"gods-love","when":"wanting to grasp how much God loves me","mean":"Christ's love is so vast it exceeds what I can measure or reason out, yet I am invited to know it by experience and be filled by it."},{"id":"isaiah-43-4","ref":"Isaiah 43:4","kjv":"Since thou wast precious in my sight, thou hast been honourable, and I have loved thee: therefore will I give men for thee, and people for thy life.","say":"I am precious and honourable in God's sight, and He has loved me.","theme":"gods-love","when":"feeling worthless","mean":"God assigns me worth and honour simply because He loves me, so my value is declared by Him and not by my achievements or others' opinions."},{"id":"isaiah-49-16","ref":"Isaiah 49:16","kjv":"Behold, I have graven thee upon the palms of my hands; thy walls are continually before me.","say":"God has graven me upon the palms of His hands; I am never forgotten, but continually before Him.","theme":"gods-love","when":"feeling overlooked or forgotten","mean":"I am engraved on God's own hands, a permanent and costly mark, and He Himself promises 'I will not forget thee' (v15), so He can no more forget me than He could forget Himself."},{"id":"isaiah-54-10","ref":"Isaiah 54:10","kjv":"For the mountains shall depart, and the hills be removed; but my kindness shall not depart from thee, neither shall the covenant of my peace be removed, saith the LORD that hath mercy on thee.","say":"Though the mountains depart and the hills be removed, God's kindness shall not depart from me, nor the covenant of His peace be removed.","theme":"gods-love","when":"fear of abandonment or life shaken","mean":"God's covenant love is more stable than the mountains, so even when everything solid shifts, His kindness toward me holds firm."},{"id":"jeremiah-31-3","ref":"Jeremiah 31:3","kjv":"The LORD hath appeared of old unto me, saying, Yea, I have loved thee with an everlasting love: therefore with lovingkindness have I drawn thee.","say":"The Lord has loved me with an everlasting love, and with lovingkindness He has drawn me to Himself.","theme":"gods-love","when":"feeling unloved or forgotten","mean":"God's love for me is not new or fragile but eternal, so it predates my failures and will outlast them, and I rest in a love that drew me before I ever sought Him."},{"id":"john-15-9","ref":"John 15:9","kjv":"As the Father hath loved me, so have I loved you: continue ye in my love.","say":"As the Father has loved the Son, so Christ has loved me; and I continue in His love.","theme":"gods-love","when":"insecurity about God's love","mean":"Jesus loves me with the very same love the Father pours on Him, so I make my home in that love rather than striving to earn it."},{"id":"john-16-27","ref":"John 16:27","kjv":"For the Father himself loveth you, because ye have loved me, and have believed that I came out from God.","say":"The Father Himself loves me, because I have loved His Son and believed that He came from God.","theme":"gods-love","when":"feeling distant from God","mean":"I do not have to win the Father's affection through any intermediary, for because I love and trust Christ, the Father Himself loves me directly and personally."},{"id":"lamentations-3-22-23","ref":"Lamentations 3:22-23","kjv":"It is of the LORD’s mercies that we are not consumed, because his compassions fail not. They are new every morning: great is thy faithfulness.","say":"It is of the LORD's mercies that I am not consumed, for His compassions fail not; they are new every morning, and great is His faithfulness.","theme":"gods-love","when":"despair or a hard season, a fresh morning","mean":"God's mercy is the reason I am still standing, and it is renewed every single morning, so each new day I draw on a fresh supply of His faithful love."},{"id":"psalm-103-11","ref":"Psalms 103:11","kjv":"For as the heaven is high above the earth, so great is his mercy toward them that fear him.","say":"As the heavens are high above the earth, so great is God's mercy toward me, for I fear Him.","theme":"gods-love","when":"feeling condemned","mean":"God's mercy toward me is measured by the height of heaven and not by the size of my sin, so I can draw near to Him unafraid."},{"id":"psalm-18-19","ref":"Psalms 18:19","kjv":"He brought me forth also into a large place; he delivered me, because he delighted in me.","say":"God has brought me forth into a large place; He delivered me because He delighted in me.","theme":"gods-love","when":"feeling trapped or boxed in","mean":"God's delight in me is the very reason He rescues me and gives me room, so His deliverance flows from affection and not obligation."},{"id":"romans-5-8","ref":"Romans 5:8","kjv":"But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.","say":"God commends His love toward me, in that while I was yet a sinner, Christ died for me.","theme":"gods-love","when":"guilt or feeling unworthy","mean":"God proved His love at my worst and not my best, so His love never depended on my goodness and cannot be forfeited by my sin."},{"id":"romans-8-32","ref":"Romans 8:32","kjv":"He that spared not his own Son, but delivered him up for us all, how shall he not with him also freely give us all things?","say":"He who spared not His own Son, but delivered Him up for me, will with Him also freely give me all things.","theme":"gods-love","when":"doubting God's care or provision","mean":"Since God already gave the greatest gift, His own Son at the cross, I can trust His love will not withhold any lesser good I truly need."},{"id":"romans-8-38-39","ref":"Romans 8:38-39","kjv":"For I am persuaded, that neither death, nor life, nor angels, nor principalities, nor powers, nor things present, nor things to come, Nor height, nor depth, nor any other creature, shall be able to separate us from the love of God, which is in Christ Jesus our Lord.","say":"I am persuaded that nothing in all creation - neither death nor life, nor things present nor things to come - can separate me from the love of God which is in Christ Jesus my Lord.","theme":"gods-love","when":"fear, shame, or feeling cut off from God","mean":"No circumstance, failure, or power can sever the love God has fixed on me in Christ, so my security rests in His grip and not in my performance."},{"id":"song-of-solomon-2-4","ref":"Song of Solomon 2:4","kjv":"He brought me to the banqueting house, and his banner over me was love.","say":"He has brought me to His banqueting house, and His banner over me is love.","theme":"gods-love","when":"feeling exposed or needing covering","mean":"God publicly claims me under the banner of His love, so I am welcomed, covered, and feasted rather than merely permitted at the edges."},{"id":"zephaniah-3-17","ref":"Zephaniah 3:17","kjv":"The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.","say":"The Lord my God in the midst of me is mighty; He rejoices over me with joy, He rests in His love, and He joys over me with singing.","theme":"gods-love","when":"weary or feeling unseen","mean":"God is not merely tolerating me; He delights in me so deeply that He sings over me, so His joy and not my strength is what holds me up."},{"id":"1-chronicles-28-20","ref":"1 Chronicles 28:20","kjv":"And David said to Solomon his son, Be strong and of good courage, and do it: fear not, nor be dismayed: for the LORD God, even my God, will be with thee; he will not fail thee, nor forsake thee, until thou hast finished all the work for the service of the house of the LORD.","say":"I will be strong and of good courage and do the work, not fearing nor dismayed, for the LORD God, my God, is with me; He will not fail me nor forsake me until all the work is finished.","theme":"gods-presence","when":"daunting project / calling","mean":"God's with-me presence sustains me not only at the start but all the way until the work He assigned is complete."},{"id":"2-timothy-4-17","ref":"2 Timothy 4:17","kjv":"Notwithstanding the Lord stood with me, and strengthened me; that by me the preaching might be fully known, and that all the Gentiles might hear: and I was delivered out of the mouth of the lion.","say":"Even when others forsake me, the Lord stands with me and strengthens me, and He delivers me out of the mouth of the lion.","theme":"gods-presence","when":"abandoned by people / standing alone","mean":"Paul's testimony is that when everyone left, the Lord stayed and strengthened him, and that same Lord stands with me."},{"id":"acts-18-10","ref":"Acts 18:10","kjv":"For I am with thee, and no man shall set on thee to hurt thee: for I have much people in this city.","say":"The Lord is with me, and He has His people and a purpose for me where He has placed me, so I will speak and not be silent out of fear.","theme":"gods-presence","when":"fear in ministry / new place","mean":"God's presence came to Paul with a commission to keep speaking, so His nearness emboldens me to be faithful where He has set me."},{"id":"deuteronomy-31-6","ref":"Deuteronomy 31:6","kjv":"Be strong and of a good courage, fear not, nor be afraid of them: for the LORD thy God, he it is that doth go with thee; he will not fail thee, nor forsake thee.","say":"I am strong and of good courage and will not be afraid, for the LORD my God goes with me; He will not fail me nor forsake me.","theme":"gods-presence","when":"facing opposition","mean":"Courage is commanded because God's going-with-me is certain, so I face what is ahead leaning on His faithfulness, not my nerve."},{"id":"deuteronomy-31-8","ref":"Deuteronomy 31:8","kjv":"And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.","say":"The LORD Himself goes before me; He is with me and will not fail me nor forsake me. I will not fear nor be dismayed.","theme":"gods-presence","when":"anxious about the future","mean":"God is already ahead of me in what I dread, so the future I am walking into is one He has already entered."},{"id":"exodus-33-14","ref":"Exodus 33:14","kjv":"And he said, My presence shall go with thee, and I will give thee rest.","say":"God's presence goes with me, and in His presence He gives me rest.","theme":"gods-presence","when":"weary / seeking rest","mean":"True rest is not found in a change of circumstances but in the God who promises His presence will go with me."},{"id":"genesis-28-15","ref":"Genesis 28:15","kjv":"And, behold, I am with thee, and will keep thee in all places whither thou goest, and will bring thee again into this land; for I will not leave thee, until I have done that which I have spoken to thee of.","say":"God is with me and keeps me in all places where I go, and He will not leave me until He has done all He has promised.","theme":"gods-presence","when":"away from home / in transition","mean":"Like Jacob at Bethel, I am kept by a God whose presence travels with me and who finishes what He has spoken."},{"id":"hebrews-12-22","ref":"Hebrews 12:22","kjv":"But ye are come unto mount Sion, and unto the city of the living God, the heavenly Jerusalem, and to an innumerable company of angels,","say":"I am come unto mount Sion, unto the city of the living God, the heavenly Jerusalem, and to an innumerable company of angels.","theme":"gods-presence","when":"feeling alone or isolated","mean":"By faith I have already come to God's heavenly city and its vast assembly, so I am never truly alone in my walk with Him."},{"id":"hebrews-13-5","ref":"Hebrews 13:5","kjv":"Let your conversation be without covetousness; and be content with such things as ye have: for he hath said, I will never leave thee, nor forsake thee.","say":"Because God Himself has said, 'I will never leave thee, nor forsake thee,' I am content with what I have and will not fear; His abiding presence is my security.","theme":"gods-presence","when":"weary / financial pressure","mean":"God's own promise of unbroken presence is the ground for my contentment, so I lean on Him rather than on what I have or lack."},{"id":"isaiah-41-10","ref":"Isaiah 41:10","kjv":"Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.","say":"I will not fear, for God is with me; I will not be dismayed, for He is my God. He strengthens me, He helps me, and He upholds me with the right hand of His righteousness.","theme":"gods-presence","when":"afraid / overwhelmed","mean":"God answers my fear with reasons — His presence, His strength, His upholding hand — and I rest my whole weight on them."},{"id":"isaiah-43-2","ref":"Isaiah 43:2","kjv":"When thou passest through the waters, I will be with thee; and through the rivers, they shall not overflow thee: when thou walkest through the fire, thou shalt not be burned; neither shall the flame kindle upon thee.","say":"When I pass through the waters, God is with me; through the rivers, they shall not overflow me; through the fire, I shall not be burned.","theme":"gods-presence","when":"deep trial","mean":"God does not promise me no waters or fire, but His presence in them that keeps them from destroying me."},{"id":"john-14-18","ref":"John 14:18","kjv":"I will not leave you comfortless: I will come to you.","say":"Jesus will not leave me comfortless; He comes to me by His Spirit.","theme":"gods-presence","when":"lonely / bereaved","mean":"Christ promised not to leave His own as orphans but to come to them in the Comforter, so I am never truly alone."},{"id":"joshua-1-9","ref":"Joshua 1:9","kjv":"Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.","say":"I am strong and of good courage; I am not afraid nor dismayed, for the LORD my God is with me wherever I go.","theme":"gods-presence","when":"new assignment / big decision","mean":"God's with-me-everywhere presence is the reason I can move forward courageously into unfamiliar ground."},{"id":"matthew-1-23","ref":"Matthew 1:23","kjv":"Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us.","say":"Jesus is Emmanuel — God with us — so God is truly with me, near in His Son and not far off.","theme":"gods-presence","when":"assurance / feeling distant from God","mean":"The name Emmanuel declares that in Christ God has come to be with His people, so His nearness is a settled fact, not a feeling."},{"id":"matthew-28-20","ref":"Matthew 28:20","kjv":"Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.","say":"As I go about my Father's business, Jesus is with me always — every single day, even unto the end of the world.","theme":"gods-presence","when":"feeling alone in the work","mean":"Christ's parting promise guarantees His companionship in obedience, so I never serve, step out, or finish the day alone."},{"id":"psalm-23-4","ref":"Psalms 23:4","kjv":"Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.","say":"Though I walk through the valley of the shadow of death, I will fear no evil, for Thou art with me; Thy rod and Thy staff, they comfort me.","theme":"gods-presence","when":"grief / facing death","mean":"Even in the darkest valley it is the Shepherd's nearness, not the absence of darkness, that takes away my fear."},{"id":"psalm-46-1","ref":"Psalms 46:1","kjv":"God is our refuge and strength, a very present help in trouble.","say":"God is my refuge and strength, a very present help in my time of trouble.","theme":"gods-presence","when":"crisis / sudden trouble","mean":"In trouble God is not distant but a help that is very present, so I run to Him first and at once."},{"id":"psalm-73-23","ref":"Psalms 73:23","kjv":"Nevertheless I am continually with thee: thou hast holden me by my right hand.","say":"Nevertheless I am continually with God; He holds me by my right hand.","theme":"gods-presence","when":"after failure / doubting","mean":"Even when my heart has slipped, God keeps hold of me, so my security rests in His grip and not in mine."},{"id":"1-peter-2-24","ref":"1 Peter 2:24","kjv":"Who his own self bare our sins in his own body on the tree, that we, being dead to sins, should live unto righteousness: by whose stripes ye were healed.","say":"Jesus bore my sins in His own body on the tree, that I, being dead to sin, might live unto righteousness; by His stripes I am healed.","theme":"health-healing","when":"Resting on the atonement while recovering","mean":"On the cross Christ carried my sins so that I could die to sin and live to righteousness; His wounds purchased my healing, which I receive as His finished work, not as something I earn."},{"id":"exodus-15-26","ref":"Exodus 15:26","kjv":"And said, If thou wilt diligently hearken to the voice of the LORD thy God, and wilt do that which is right in his sight, and wilt give ear to his commandments, and keep all his statutes, I will put none of these diseases upon thee, which I have brought upon the Egyptians: for I am the LORD that healeth thee.","say":"I diligently hearken to the voice of the LORD my God and do what is right in His sight; for He is the LORD that healeth me.","theme":"health-healing","when":"new symptoms, seeking the Healer","mean":"God reveals Himself as Jehovah-Rapha, my Healer, as I walk in obedience to His voice; so I keep listening and trusting Him with my health."},{"id":"exodus-23-25","ref":"Exodus 23:25","kjv":"And ye shall serve the LORD your God, and he shall bless thy bread, and thy water; and I will take sickness away from the midst of thee.","say":"I serve the LORD my God; He blesses my bread and my water, and takes sickness away from the midst of me.","theme":"health-healing","when":"daily provision and protection from sickness","mean":"As I serve the LORD He blesses my daily sustenance and removes sickness, so I receive wholeness from His covenant hand."},{"id":"isaiah-53-5","ref":"Isaiah 53:5","kjv":"But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed.","say":"Christ was wounded for my transgressions and bruised for my iniquities; the chastisement of my peace was upon Him, and with His stripes I am healed.","theme":"health-healing","when":"Facing chronic pain or a hard diagnosis","mean":"The same substitutionary suffering that bore my sin also secured my peace and my healing; I trust the cross for both my soul and my body."},{"id":"jeremiah-17-14","ref":"Jeremiah 17:14","kjv":"Heal me, O LORD, and I shall be healed; save me, and I shall be saved: for thou art my praise.","say":"Heal me, O LORD, and I shall be healed; save me, and I shall be saved; for Thou art my praise.","theme":"health-healing","when":"crying out in desperation for healing","mean":"Lasting healing and salvation come from the LORD alone, so I bring my need to Him directly and make Him my praise."},{"id":"jeremiah-30-17","ref":"Jeremiah 30:17","kjv":"For I will restore health unto thee, and I will heal thee of thy wounds, saith the LORD; because they called thee an Outcast, saying, This is Zion, whom no man seeketh after.","say":"The LORD restores health unto me and heals me of my wounds; for so He has said.","theme":"health-healing","when":"recovering from a wound, or being written off by others","mean":"God is personally committed to restoring and healing me, even when others have given up on my case."},{"id":"jeremiah-33-6","ref":"Jeremiah 33:6","kjv":"Behold, I will bring it health and cure, and I will cure them, and will reveal unto them the abundance of peace and truth.","say":"The LORD brings me health and cure, and reveals to me the abundance of peace and truth.","theme":"health-healing","when":"awaiting results, needing both cure and peace","mean":"God promises both cure and peace, so I wait on Him for the whole-person restoration only He can give."},{"id":"malachi-4-2","ref":"Malachi 4:2","kjv":"But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall.","say":"Because I fear His name, the Sun of righteousness arises upon me with healing in His wings; I go forth and grow strong.","theme":"health-healing","when":"the dawn of a new day in a long battle","mean":"For those who revere God, Christ the Sun of righteousness rises with healing, so each new day brings His restoring light and I thrive like a well-fed calf."},{"id":"matthew-8-17","ref":"Matthew 8:17","kjv":"That it might be fulfilled which was spoken by Esaias the prophet, saying, Himself took our infirmities, and bare our sicknesses.","say":"Jesus Himself took my infirmities and bare my sicknesses; I rest in the finished work of my Savior.","theme":"health-healing","when":"resting in Christ's finished work","mean":"Christ already carried my sicknesses at Calvary, so I stand on His completed work rather than striving in my own strength."},{"id":"proverbs-3-8","ref":"Proverbs 3:8","kjv":"It shall be health to thy navel, and marrow to thy bones.","say":"As I fear the LORD and depart from evil, it is health to my navel and marrow to my bones.","theme":"health-healing","when":"stressed or tempted, needing bodily wellness","mean":"Reverent, holy living brings real benefit to my body, so wellness and walking rightly before God belong together."},{"id":"proverbs-4-22","ref":"Proverbs 4:22","kjv":"For they are life unto those that find them, and health to all their flesh.","say":"God's words are life unto me and health to all my flesh; I have found them and I keep them in the midst of my heart.","theme":"health-healing","when":"soaking in the Word for healing","mean":"God's word, treasured in my heart, is life and medicine to my whole body, so I keep attending to Scripture day by day."},{"id":"psalms-103-3","ref":"Psalms 103:3","kjv":"Who forgiveth all thine iniquities; who healeth all thy diseases;","say":"The LORD forgives all my iniquities and heals all my diseases; I bless Him and forget not all His benefits.","theme":"health-healing","when":"carrying guilt and sickness together","mean":"Forgiveness and healing are joined among God's benefits, so I receive both freely from the same gracious hand."},{"id":"psalms-118-17","ref":"Psalms 118:17","kjv":"I shall not die, but live, and declare the works of the LORD.","say":"I shall not die, but live, and declare the works of the LORD.","theme":"health-healing","when":"facing a frightening or life-threatening report","mean":"I declare life over myself for the purpose of testifying to God's works, trusting Him above the grimmest report."},{"id":"psalms-91-16","ref":"Psalms 91:16","kjv":"With long life will I satisfy him, and shew him my salvation.","say":"With long life the LORD satisfies me, and shows me His salvation.","theme":"health-healing","when":"fearing an early death, longing for length of days","mean":"Long and satisfied life is God's gift to those who dwell in Him, so I trust Him with my days instead of fearing them."},{"id":"1-corinthians-10-13","ref":"1 Corinthians 10:13","kjv":"There hath no temptation taken you but such as is common to man: but God is faithful, who will not suffer you to be tempted above that ye are able; but will with the temptation also make a way to escape, that ye may be able to bear it.","say":"No temptation takes me but such as is common to man; God is faithful, and with every temptation He makes a way of escape, that I may be able to bear it.","theme":"holiness-victory-over-sin","when":"under temptation","mean":"God never lets temptation exceed what His grace can carry me through, so in the heat of it I look for the escape He has already provided rather than believing I have no choice but to fall."},{"id":"1-peter-2-11","ref":"1 Peter 2:11","kjv":"Dearly beloved, I beseech you as strangers and pilgrims, abstain from fleshly lusts, which war against the soul;","say":"As a stranger and pilgrim here, I abstain from fleshly lusts, which war against my soul.","theme":"holiness-victory-over-sin","when":"tempted by what the world offers","mean":"Because I am only passing through this world on my way home to God, I refuse fleshly cravings, recognising them as enemies waging war against my own soul."},{"id":"2-corinthians-7-1","ref":"2 Corinthians 7:1","kjv":"Having therefore these promises, dearly beloved, let us cleanse ourselves from all filthiness of the flesh and spirit, perfecting holiness in the fear of God.","say":"Having these promises, I cleanse myself from all filthiness of the flesh and spirit, perfecting holiness in the fear of God.","theme":"holiness-victory-over-sin","when":"pursuing deeper purity","mean":"Resting on God's promises, I take responsibility to clear out defilement in both body and spirit, growing toward a maturing holiness rooted in reverent fear of God."},{"id":"2-timothy-2-22","ref":"2 Timothy 2:22","kjv":"Flee also youthful lusts: but follow righteousness, faith, charity, peace, with them that call on the Lord out of a pure heart.","say":"I flee youthful lusts and follow righteousness, faith, charity, and peace, calling on the Lord out of a pure heart.","theme":"holiness-victory-over-sin","when":"sexual or impulsive temptation","mean":"Some sins are to be run from, not reasoned with; I both flee what defiles and pursue the good things of God in the company of other sincere believers."},{"id":"ephesians-4-24","ref":"Ephesians 4:24","kjv":"And that ye put on the new man, which after God is created in righteousness and true holiness.","say":"I put on the new man, which after God is created in righteousness and true holiness.","theme":"holiness-victory-over-sin","when":"wanting to break an old pattern","mean":"In Christ a new self already exists, created like God in righteousness and holiness, so change means deliberately putting on who I truly am now."},{"id":"galatians-5-16","ref":"Galatians 5:16","kjv":"This I say then, Walk in the Spirit, and ye shall not fulfil the lust of the flesh.","say":"I walk in the Spirit, and I do not fulfil the lust of the flesh.","theme":"holiness-victory-over-sin","when":"fighting the flesh","mean":"Victory over sin is less about gritting my teeth against the flesh and more about staying surrendered to and led by the Holy Spirit, who starves the flesh of its power as I follow Him."},{"id":"jude-1-24","ref":"Jude 1:24","kjv":"Now unto him that is able to keep you from falling, and to present you faultless before the presence of his glory with exceeding joy,","say":"My God is able to keep me from falling and to present me faultless before the presence of His glory with exceeding joy.","theme":"holiness-victory-over-sin","when":"afraid of stumbling spiritually","mean":"God's own power, not my willpower, keeps me from falling and will present me blameless before His glory; the guarding and the finishing of my faith are His work."},{"id":"proverbs-28-13","ref":"Proverbs 28:13","kjv":"He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy.","say":"I will not cover my sins, for one who hides them shall not prosper; I confess and forsake them, and I obtain mercy.","theme":"holiness-victory-over-sin","when":"tempted to hide a fault","mean":"Concealing sin keeps me stuck, but open confession joined with genuinely turning away from it is the path on which God grants mercy."},{"id":"psalm-139-23-24","ref":"Psalms 139:23-24","kjv":"Search me, O God, and know my heart: try me, and know my thoughts: And see if there be any wicked way in me, and lead me in the way everlasting.","say":"Search me, O God, and know my heart; try me, and know my thoughts; see if there be any wicked way in me, and lead me in the way everlasting.","theme":"holiness-victory-over-sin","when":"examining my own heart","mean":"I invite God to expose the hidden sin I cannot see on my own and to lead me out of it into His everlasting way, trusting His searching as the mercy that keeps me holy."},{"id":"psalms-119-11","ref":"Psalms 119:11","kjv":"Thy word have I hid in mine heart, that I might not sin against thee.","say":"Thy word have I hid in mine heart, that I might not sin against Thee.","theme":"holiness-victory-over-sin","when":"guarding my heart daily","mean":"The Scripture I store up inside me becomes a living defence in the moment of temptation, so I treasure God's word now to keep from sinning against Him later."},{"id":"psalms-51-10","ref":"Psalms 51:10","kjv":"Create in me a clean heart, O God; and renew a right spirit within me.","say":"Create in me a clean heart, O God, and renew a right spirit within me.","theme":"holiness-victory-over-sin","when":"after I have failed","mean":"When I have sinned I do not only ask forgiveness but ask God to do a creative work inside me, giving me a clean heart and a steady spirit that only He can make."},{"id":"romans-13-14","ref":"Romans 13:14","kjv":"But put ye on the Lord Jesus Christ, and make not provision for the flesh, to fulfil the lusts thereof.","say":"I put on the Lord Jesus Christ, and I make no provision for the flesh to fulfil its lusts.","theme":"holiness-victory-over-sin","when":"setting boundaries","mean":"Holiness means clothing myself with Christ and refusing to arrange the circumstances and inputs that would give my flesh its ammunition."},{"id":"romans-6-11","ref":"Romans 6:11","kjv":"Likewise reckon ye also yourselves to be dead indeed unto sin, but alive unto God through Jesus Christ our Lord.","say":"I reckon myself to be dead indeed unto sin, but alive unto God through Jesus Christ my Lord.","theme":"holiness-victory-over-sin","when":"fighting a stubborn sin","mean":"Sin no longer holds rightful mastery over me, so I count on the death and resurrection of Christ as true of me and meet temptation as one already alive to God."},{"id":"romans-6-14","ref":"Romans 6:14","kjv":"For sin shall not have dominion over you: for ye are not under the law, but under grace.","say":"Sin shall not have dominion over me, for I am not under the law, but under grace.","theme":"holiness-victory-over-sin","when":"a besetting sin","mean":"Because I belong to Christ and live under grace, sin has lost its right to rule me; it may tempt, but it no longer owns me, and I stand on that settled fact."},{"id":"titus-2-12","ref":"Titus 2:12","kjv":"Teaching us that, denying ungodliness and worldly lusts, we should live soberly, righteously, and godly, in this present world;","say":"The grace of God teaches me to deny ungodliness and worldly lusts, and to live soberly, righteously, and godly in this present world.","theme":"holiness-victory-over-sin","when":"living godly in a godless culture","mean":"The same grace that saved me actively trains me to say no to sin and yes to a sober, upright, godly life right here in the present age."},{"id":"1-corinthians-1-30","ref":"1 Corinthians 1:30","kjv":"But of him are ye in Christ Jesus, who of God is made unto us wisdom, and righteousness, and sanctification, and redemption:","say":"I am in Christ Jesus, who of God is made unto me wisdom, righteousness, sanctification, and redemption.","theme":"identity-in-christ","when":"feeling I lack wisdom or righteousness","mean":"Everything I need to stand before God, Christ Himself has become for me, so I boast in Him and not in my own merit."},{"id":"1-corinthians-3-23","ref":"1 Corinthians 3:23","kjv":"And ye are Christ’s; and Christ is God’s.","say":"I am Christ's, and Christ is God's.","theme":"identity-in-christ","when":"feeling pulled in many directions, asking who I belong to","mean":"I belong wholly to Christ, who belongs to God, so my life is held secure within that unbroken chain of ownership and love."},{"id":"1-corinthians-6-11","ref":"1 Corinthians 6:11","kjv":"And such were some of you: but ye are washed, but ye are sanctified, but ye are justified in the name of the Lord Jesus, and by the Spirit of our God.","say":"Such was I once; but now I am washed, I am sanctified, I am justified in the name of the Lord Jesus, and by the Spirit of our God.","theme":"identity-in-christ","when":"defined by who I used to be","mean":"Whatever my former life was, God's threefold work has washed, set apart, and justified me, so my identity is now what His grace has made me, not my past."},{"id":"1-john-1-9","ref":"1 John 1:9","kjv":"If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.","say":"When I confess my sins, He is faithful and just to forgive me and to cleanse me from all unrighteousness.","theme":"identity-in-christ","when":"after I have sinned and need to repent","mean":"Honest confession is met not with reluctance but with God's faithful justice, so after a fall I come openly and receive full cleansing."},{"id":"1-john-3-1","ref":"1 John 3:1","kjv":"Behold, what manner of love the Father hath bestowed upon us, that we should be called the sons of God: therefore the world knoweth us not, because it knew him not.","say":"Behold what manner of love the Father has bestowed upon me, that I should be called a son of God.","theme":"identity-in-christ","when":"feeling unloved or rejected","mean":"The Father's lavish love has named me His own, so even when the world does not recognize me, my identity is secure in His love."},{"id":"1-peter-1-4","ref":"1 Peter 1:4","kjv":"To an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for you,","say":"I have an inheritance incorruptible, and undefiled, and that fadeth not away, reserved in heaven for me.","theme":"identity-in-christ","when":"loss, when earthly things are falling apart","mean":"My true inheritance is kept safe in heaven beyond all decay, so earthly loss cannot touch what God is holding for me in Christ."},{"id":"1-peter-2-9","ref":"1 Peter 2:9","kjv":"But ye are a chosen generation, a royal priesthood, an holy nation, a peculiar people; that ye should shew forth the praises of him who hath called you out of darkness into his marvellous light:","say":"I am part of a chosen generation, a royal priesthood, a holy nation, called to show forth the praises of Him who called me out of darkness into His marvellous light.","theme":"identity-in-christ","when":"questioning my worth or identity","mean":"My true identity in Christ is royal and priestly, given so I can worship and declare His praise rather than scramble to earn my own worth."},{"id":"2-corinthians-3-18","ref":"2 Corinthians 3:18","kjv":"But we all, with open face beholding as in a glass the glory of the Lord, are changed into the same image from glory to glory, even as by the Spirit of the Lord.","say":"With open face I behold the glory of the Lord, and I am changed into the same image, from glory to glory, by the Spirit of the Lord.","theme":"identity-in-christ","when":"discouraged by slow spiritual growth","mean":"As I keep gazing on Jesus, the Spirit steadily transforms me into His likeness in stages, so I trust the process rather than demanding instant perfection."},{"id":"2-corinthians-5-17","ref":"2 Corinthians 5:17","kjv":"Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new.","say":"I am in Christ, therefore I am a new creature: old things are passed away; behold, all things are become new.","theme":"identity-in-christ","when":"haunted by my past","mean":"Because I am united to Christ, God no longer defines me by who I used to be, so I can stand on a genuinely new identity rather than my old record."},{"id":"2-corinthians-5-21","ref":"2 Corinthians 5:21","kjv":"For he hath made him to be sin for us, who knew no sin; that we might be made the righteousness of God in him.","say":"In Christ, who knew no sin and was made sin for me, I am made the very righteousness of God in Him.","theme":"identity-in-christ","when":"feeling unworthy before God","mean":"My righteousness is a gift credited to me because Jesus took my sin, so I stand before God clothed in His own righteousness, not my performance."},{"id":"2-corinthians-6-18","ref":"2 Corinthians 6:18","kjv":"And will be a Father unto you, and ye shall be my sons and daughters, saith the Lord Almighty.","say":"The Lord Almighty is a Father unto me, and I am His own child, saith the Lord Almighty.","theme":"identity-in-christ","when":"fatherlessness, needing a Father","mean":"The Almighty God Himself has pledged to be my Father, so I relate to Him with the intimacy and security of His own child."},{"id":"2-peter-1-3","ref":"2 Peter 1:3","kjv":"According as his divine power hath given unto us all things that pertain unto life and godliness, through the knowledge of him that hath called us to glory and virtue:","say":"God's divine power has given me all things that pertain unto life and godliness, through the knowledge of Him who called me to glory and virtue.","theme":"identity-in-christ","when":"feeling ill-equipped for a godly life","mean":"God has already supplied all I need to live for Him, accessed by knowing Christ rather than by my own sufficiency."},{"id":"colossians-1-13","ref":"Colossians 1:13","kjv":"Who hath delivered us from the power of darkness, and hath translated us into the kingdom of his dear Son:","say":"God has delivered me from the power of darkness and translated me into the kingdom of His dear Son.","theme":"identity-in-christ","when":"feeling oppressed or under the enemy's power","mean":"I have already been moved out of darkness's jurisdiction into Christ's kingdom, so I stand as a citizen of His reign, not a captive of the enemy."},{"id":"colossians-1-22","ref":"Colossians 1:22","kjv":"In the body of his flesh through death, to present you holy and unblameable and unreproveable in his sight:","say":"In the body of His flesh through death, Christ presents me holy, and unblameable, and unreproveable in His sight.","theme":"identity-in-christ","when":"feeling I always fall short","mean":"Through His death Christ now presents me to God as holy and beyond reproach, so I accept the standing He gives rather than measuring myself by my shortfalls."},{"id":"colossians-1-27","ref":"Colossians 1:27","kjv":"To whom God would make known what is the riches of the glory of this mystery among the Gentiles; which is Christ in you, the hope of glory:","say":"The mystery is made known: Christ in me, the hope of glory.","theme":"identity-in-christ","when":"feeling ordinary or without purpose","mean":"The living Christ dwells in me as my sure hope of glory, so my life carries His presence and His future even when I feel unremarkable."},{"id":"colossians-2-10","ref":"Colossians 2:10","kjv":"And ye are complete in him, which is the head of all principality and power:","say":"I am complete in Him, who is the head of all principality and power.","theme":"identity-in-christ","when":"feeling inadequate or not enough","mean":"My completeness rests in Christ, not in my performance, so I rest in His fullness instead of striving to prove myself."},{"id":"colossians-2-14","ref":"Colossians 2:14","kjv":"Blotting out the handwriting of ordinances that was against us, which was contrary to us, and took it out of the way, nailing it to his cross;","say":"The handwriting that was against me He has blotted out, taking it out of the way and nailing it to His cross.","theme":"identity-in-christ","when":"condemned by a record of my wrongs","mean":"The charge that stood against me was nailed to the cross of Christ, so the debt is cancelled and can never be presented against me again."},{"id":"colossians-3-3","ref":"Colossians 3:3","kjv":"For ye are dead, and your life is hid with Christ in God.","say":"I am dead, and my life is hid with Christ in God.","theme":"identity-in-christ","when":"feeling exposed or insecure","mean":"My real identity and security are hidden safely in Christ, beyond the reach of man's opinion or circumstance, so I rest in where my life is actually kept."},{"id":"deuteronomy-14-1","ref":"Deuteronomy 14:1","kjv":"Ye are the children of the LORD your God: ye shall not cut yourselves, nor make any baldness between your eyes for the dead.","say":"I am a child of the LORD my God, set apart as His own.","theme":"identity-in-christ","when":"needing a settled, holy identity","mean":"Spoken first over Israel as God's children and confirmed in Christ, this names me as His own and calls me to live set apart to Him."},{"id":"deuteronomy-7-6","ref":"Deuteronomy 7:6","kjv":"For thou art an holy people unto the LORD thy God: the LORD thy God hath chosen thee to be a special people unto himself, above all people that are upon the face of the earth.","say":"I am part of a holy people unto the Lord my God, chosen to be His own special people.","theme":"identity-in-christ","when":"feeling unchosen or overlooked","mean":"God's heart to choose a people for Himself, shown to Israel, is mine in Christ (1 Peter 2:9; Titus 2:14), so I am set apart and treasured by Him rather than overlooked."},{"id":"ephesians-1-3","ref":"Ephesians 1:3","kjv":"Blessed be the God and Father of our Lord Jesus Christ, who hath blessed us with all spiritual blessings in heavenly places in Christ:","say":"My God has blessed me with all spiritual blessings in heavenly places in Christ.","theme":"identity-in-christ","when":"feeling empty or spiritually dry","mean":"Every spiritual blessing I need is already given to me in Christ, so I draw on what I have in Him rather than beg for what I think I lack."},{"id":"ephesians-1-4","ref":"Ephesians 1:4","kjv":"According as he hath chosen us in him before the foundation of the world, that we should be holy and without blame before him in love:","say":"God chose me in Him before the foundation of the world, that I should be holy and without blame before Him in love.","theme":"identity-in-christ","when":"feeling rejected or unwanted","mean":"My belonging to God was settled before the world began, so no present rejection can undo His eternal choice of me."},{"id":"ephesians-1-5","ref":"Ephesians 1:5","kjv":"Having predestinated us unto the adoption of children by Jesus Christ to himself, according to the good pleasure of his will,","say":"God has predestinated me unto the adoption of children by Jesus Christ to Himself, according to the good pleasure of His will.","theme":"identity-in-christ","when":"feeling unwanted or orphaned","mean":"My adoption was God's deliberate pleasure before I ever chose Him, so my place in His family was His plan, never an afterthought."},{"id":"ephesians-1-6","ref":"Ephesians 1:6","kjv":"To the praise of the glory of his grace, wherein he hath made us accepted in the beloved.","say":"To the praise of the glory of His grace, He has made me accepted in the Beloved.","theme":"identity-in-christ","when":"feeling rejected or not good enough","mean":"I am accepted not on my own merit but in Christ the Beloved, so my acceptance is as secure as Jesus Himself."},{"id":"ephesians-1-7","ref":"Ephesians 1:7","kjv":"In whom we have redemption through his blood, the forgiveness of sins, according to the riches of his grace;","say":"In Christ I have redemption through His blood, the forgiveness of sins, according to the riches of His grace.","theme":"identity-in-christ","when":"weighed down by the cost of my sin","mean":"My forgiveness was purchased by the blood of Jesus out of the riches of grace, so I hold it as something bought at full price, not cheaply excused."},{"id":"ephesians-2-10","ref":"Ephesians 2:10","kjv":"For we are his workmanship, created in Christ Jesus unto good works, which God hath before ordained that we should walk in them.","say":"I am His workmanship, created in Christ Jesus unto good works, which God ordained beforehand that I should walk in them.","theme":"identity-in-christ","when":"questioning my value or calling","mean":"I am God's handiwork, purposefully made for good works He prepared in advance, so my life has intended meaning and a path to walk."},{"id":"ephesians-2-19","ref":"Ephesians 2:19","kjv":"Now therefore ye are no more strangers and foreigners, but fellowcitizens with the saints, and of the household of God;","say":"I am no more a stranger and foreigner, but a fellowcitizen with the saints, and of the household of God.","theme":"identity-in-christ","when":"loneliness, feeling like an outsider","mean":"In Christ I belong to God's own household and city, so I am never a spiritual outsider again."},{"id":"ephesians-2-6","ref":"Ephesians 2:6","kjv":"And hath raised us up together, and made us sit together in heavenly places in Christ Jesus:","say":"In Christ Jesus, God has raised me up together with Him and seated me in heavenly places.","theme":"identity-in-christ","when":"feeling defeated or beaten down","mean":"In Christ I already share His seated position of rest and authority above my circumstances, so I face life from victory, not merely for it."},{"id":"exodus-19-6","ref":"Exodus 19:6","kjv":"And ye shall be unto me a kingdom of priests, and an holy nation. These are the words which thou shalt speak unto the children of Israel.","say":"In Christ I belong to a kingdom of priests and a holy nation unto my God.","theme":"identity-in-christ","when":"feeling ordinary or common","mean":"What God purposed for Israel is fulfilled for me in Christ (1 Peter 2:9), setting me apart as priestly and holy to serve and represent Him."},{"id":"ezekiel-36-26","ref":"Ezekiel 36:26","kjv":"A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.","say":"God has given me a new heart, and put a new spirit within me; He has taken away the stony heart out of my flesh, and given me a heart of flesh.","theme":"identity-in-christ","when":"feeling hard-hearted or cold toward God","mean":"A tender, responsive heart is God's own gift of the new covenant, not something I manufacture, so when I feel hard I rest in the new heart He has given."},{"id":"galatians-2-20","ref":"Galatians 2:20","kjv":"I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me: and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave himself for me.","say":"I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me; and the life which I now live in the flesh I live by the faith of the Son of God, who loved me, and gave Himself for me.","theme":"identity-in-christ","when":"trying to live right in my own strength","mean":"My Christian life is not me striving harder but the living Christ within me, so I lean on His indwelling life and His love rather than my willpower."},{"id":"galatians-3-26","ref":"Galatians 3:26","kjv":"For ye are all the children of God by faith in Christ Jesus.","say":"I am a child of God by faith in Christ Jesus.","theme":"identity-in-christ","when":"identity doubt","mean":"My sonship comes through faith in Christ alone, so my family membership is grounded in Him and never in my background or works."},{"id":"galatians-3-29","ref":"Galatians 3:29","kjv":"And if ye be Christ’s, then are ye Abraham’s seed, and heirs according to the promise.","say":"Because I am Christ's, I am Abraham's seed, and an heir according to the promise.","theme":"identity-in-christ","when":"wondering whether God's promises are really for me","mean":"Belonging to Christ grafts me into Abraham's covenant line, so the promises of God are mine by faith, not by lineage."},{"id":"galatians-4-7","ref":"Galatians 4:7","kjv":"Wherefore thou art no more a servant, but a son; and if a son, then an heir of God through Christ.","say":"I am no more a servant but a son, and if a son, then an heir of God through Christ.","theme":"identity-in-christ","when":"striving, feeling like a slave to duty","mean":"In Christ my standing before God is settled as a son, not a hired hand, so I serve from belonging rather than to earn belonging."},{"id":"galatians-6-15","ref":"Galatians 6:15","kjv":"For in Christ Jesus neither circumcision availeth any thing, nor uncircumcision, but a new creature.","say":"In Christ Jesus neither my background nor my credentials avail anything; what counts is that I am a new creature.","theme":"identity-in-christ","when":"measuring myself by status or religion","mean":"What ultimately matters is not my religious resume or heritage but the new creation God has made me, so I rest my worth there."},{"id":"hebrews-8-12","ref":"Hebrews 8:12","kjv":"For I will be merciful to their unrighteousness, and their sins and their iniquities will I remember no more.","say":"God is merciful to my unrighteousness, and my sins and iniquities He remembers no more.","theme":"identity-in-christ","when":"accused by my own conscience","mean":"Under the new covenant God chooses to keep no record of my forgiven sins, so when memory accuses me I stand on His promise to remember them no more."},{"id":"hosea-1-10","ref":"Hosea 1:10","kjv":"Yet the number of the children of Israel shall be as the sand of the sea, which cannot be measured nor numbered; and it shall come to pass, that in the place where it was said unto them, Ye are not my people, there it shall be said unto them, Ye are the sons of the living God.","say":"In the very place where it was said I was not His people, there it is now said of me: I am a son of the living God.","theme":"identity-in-christ","when":"shame, feeling disqualified by my past","mean":"God's mercy reverses the 'not-my-people' verdict and names me His own child, so my past rejection is overturned by His grace."},{"id":"isaiah-1-18","ref":"Isaiah 1:18","kjv":"Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool.","say":"Though my sins were as scarlet, in Christ they are made white as snow; though they were red like crimson, they are made as wool.","theme":"identity-in-christ","when":"feeling stained by my past","mean":"No sin is too deep-dyed for God's cleansing, so I bring even my worst to Him and receive the spotless whiteness He promises in Christ."},{"id":"isaiah-43-1","ref":"Isaiah 43:1","kjv":"But now thus saith the LORD that created thee, O Jacob, and he that formed thee, O Israel, Fear not: for I have redeemed thee, I have called thee by thy name; thou art mine.","say":"The LORD who created me and formed me says: Fear not, for I have redeemed you, I have called you by your name; you are Mine.","theme":"identity-in-christ","when":"fear, feeling forgotten or alone","mean":"God who made me has redeemed me and claimed me by name, so I face fear knowing I personally belong to Him."},{"id":"isaiah-43-25","ref":"Isaiah 43:25","kjv":"I, even I, am he that blotteth out thy transgressions for mine own sake, and will not remember thy sins.","say":"The LORD Himself blots out my transgressions for His own sake, and will not remember my sins.","theme":"identity-in-christ","when":"afraid God still holds my sin against me","mean":"God blots out my sin for His own name's sake and chooses not to remember it, so my forgiveness rests on His character, not my worthiness."},{"id":"isaiah-61-10","ref":"Isaiah 61:10","kjv":"I will greatly rejoice in the LORD, my soul shall be joyful in my God; for he hath clothed me with the garments of salvation, he hath covered me with the robe of righteousness, as a bridegroom decketh himself with ornaments, and as a bride adorneth herself with her jewels.","say":"I greatly rejoice in the LORD, for He has clothed me with the garments of salvation and covered me with the robe of righteousness.","theme":"identity-in-christ","when":"feeling exposed or ashamed","mean":"My standing before God is a robe He Himself wraps around me, so I rejoice as one already dressed for His presence, not one trying to cover my own nakedness."},{"id":"john-1-12","ref":"John 1:12","kjv":"But as many as received him, to them gave he power to become the sons of God, even to them that believe on his name:","say":"Because I have received Him and believe on His name, He has given me power to become a son of God.","theme":"identity-in-christ","when":"assurance of salvation, identity doubt","mean":"Receiving Christ by faith is what makes me God's child, so my sonship rests on Him and not on my performance."},{"id":"micah-7-19","ref":"Micah 7:19","kjv":"He will turn again, he will have compassion upon us; he will subdue our iniquities; and thou wilt cast all their sins into the depths of the sea.","say":"He has compassion on me; He subdues my iniquities and casts all my sins into the depths of the sea.","theme":"identity-in-christ","when":"unable to forgive myself","mean":"God not only pardons but drowns my sins in the deep, so I refuse to go diving for what He has buried in the sea."},{"id":"philippians-3-20","ref":"Philippians 3:20","kjv":"For our conversation is in heaven; from whence also we look for the Saviour, the Lord Jesus Christ:","say":"My citizenship is in heaven, and from there I look for the Saviour, the Lord Jesus Christ.","theme":"identity-in-christ","when":"feeling out of place in this world","mean":"I live as a citizen of heaven passing through earth, fixing my hope on Christ's return rather than on this world's approval."},{"id":"philippians-3-9","ref":"Philippians 3:9","kjv":"And be found in him, not having mine own righteousness, which is of the law, but that which is through the faith of Christ, the righteousness which is of God by faith:","say":"I am found in Him, not having my own righteousness which is of the law, but the righteousness which is of God by faith.","theme":"identity-in-christ","when":"tempted toward self-righteousness or performance","mean":"I have stopped presenting my own record to God and instead rest entirely in Christ's righteousness received by faith, which alone makes me acceptable."},{"id":"psalm-16-6","ref":"Psalms 16:6","kjv":"The lines are fallen unto me in pleasant places; yea, I have a goodly heritage.","say":"The lines are fallen unto me in pleasant places; I have a goodly heritage.","theme":"identity-in-christ","when":"feeling shortchanged in life","mean":"With the Lord Himself as my portion (Psalm 16:5), my true inheritance is good and secure, so I give thanks instead of envying what others have."},{"id":"psalms-103-12","ref":"Psalms 103:12","kjv":"As far as the east is from the west, so far hath he removed our transgressions from us.","say":"As far as the east is from the west, so far has He removed my transgressions from me.","theme":"identity-in-christ","when":"haunted by old sins","mean":"God has put an immeasurable distance between me and my sins, so I stop dragging back what He has carried infinitely away."},{"id":"revelation-21-7","ref":"Revelation 21:7","kjv":"He that overcometh shall inherit all things; and I will be his God, and he shall be my son.","say":"As I overcome in Christ, I shall inherit all things; God shall be my God, and I shall be His son.","theme":"identity-in-christ","when":"weary in the fight of faith, tempted to give up","mean":"The one who endures in faith inherits everything, so I press on knowing God Himself is my reward and my Father."},{"id":"romans-12-2","ref":"Romans 12:2","kjv":"And be not conformed to this world: but be ye transformed by the renewing of your mind, that ye may prove what is that good, and acceptable, and perfect, will of God.","say":"I am not conformed to this world, but transformed by the renewing of my mind, that I may prove what is that good, and acceptable, and perfect will of God.","theme":"identity-in-christ","when":"pressured to think like the world","mean":"Lasting change comes as God renews my thinking through His Word, so I deliberately feed my mind on truth instead of being shaped by the culture around me."},{"id":"romans-3-24","ref":"Romans 3:24","kjv":"Being justified freely by his grace through the redemption that is in Christ Jesus:","say":"I am justified freely by His grace, through the redemption that is in Christ Jesus.","theme":"identity-in-christ","when":"trying to deserve what is already given","mean":"My justification is a free gift of grace through Christ's redemption, so I receive it with empty hands rather than trying to pay for what cannot be earned."},{"id":"romans-5-1","ref":"Romans 5:1","kjv":"Therefore being justified by faith, we have peace with God through our Lord Jesus Christ:","say":"Being justified by faith, I have peace with God through my Lord Jesus Christ.","theme":"identity-in-christ","when":"striving to earn God's acceptance","mean":"The war between me and God is over because faith in Christ has justified me, so I rest in settled peace instead of striving to deserve Him."},{"id":"romans-8-1","ref":"Romans 8:1","kjv":"There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit.","say":"There is therefore now no condemnation to me, for I am in Christ Jesus, and I walk not after the flesh, but after the Spirit.","theme":"identity-in-christ","when":"guilt and self-condemnation","mean":"Because I belong to Christ, the verdict over my life is 'no condemnation,' so I refuse the accusing voice and keep walking in step with the Spirit."},{"id":"romans-8-15","ref":"Romans 8:15","kjv":"For ye have not received the spirit of bondage again to fear; but ye have received the Spirit of adoption, whereby we cry, Abba, Father.","say":"I have not received the spirit of bondage again to fear, but the Spirit of adoption, whereby I cry, Abba, Father.","theme":"identity-in-christ","when":"fear or anxiety","mean":"The Holy Spirit assures me I am an adopted child who can call God 'Father,' freeing me from the slavery of fear."},{"id":"romans-8-17","ref":"Romans 8:17","kjv":"And if children, then heirs; heirs of God, and joint-heirs with Christ; if so be that we suffer with him, that we may be also glorified together.","say":"I am a child of God, and if a child then an heir — an heir of God and joint-heir with Christ; and if I suffer with Him, I shall also be glorified together with Him.","theme":"identity-in-christ","when":"suffering or feeling overlooked","mean":"My sonship makes me a co-heir with Jesus, so present hardship is not the end of my story but the road to shared glory with Him."},{"id":"romans-8-33-34","ref":"Romans 8:33-34","kjv":"Who shall lay any thing to the charge of God’s elect? It is God that justifieth. Who is he that condemneth? It is Christ that died, yea rather, that is risen again, who is even at the right hand of God, who also maketh intercession for us.","say":"Who shall lay any thing to my charge? It is God that justifieth. Who is he that condemneth? It is Christ that died, yea rather, that is risen again, who is even at the right hand of God, and maketh intercession for me.","theme":"identity-in-christ","when":"under accusation from the enemy","mean":"When accusations come, the Judge Himself has acquitted me and the risen Christ is pleading on my behalf, so no charge against me can stand."},{"id":"titus-3-5","ref":"Titus 3:5","kjv":"Not by works of righteousness which we have done, but according to his mercy he saved us, by the washing of regeneration, and renewing of the Holy Ghost;","say":"Not by works of righteousness which I have done, but according to His mercy He saved me, by the washing of regeneration and the renewing of the Holy Ghost.","theme":"identity-in-christ","when":"doubting my salvation on a bad day","mean":"My salvation rests on God's mercy and the Spirit's washing, not on how well I performed today, so my standing holds even when my feelings do not."},{"id":"titus-3-7","ref":"Titus 3:7","kjv":"That being justified by his grace, we should be made heirs according to the hope of eternal life.","say":"Being justified by His grace, I am made an heir according to the hope of eternal life.","theme":"identity-in-christ","when":"guilt, uncertain about my standing and my future","mean":"Grace both justifies me and makes me an heir, so eternal life is a settled inheritance I receive by His mercy, not a wage I must earn."},{"id":"1-corinthians-13-4","ref":"1 Corinthians 13:4","kjv":"Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,","say":"In my marriage my love suffers long and is kind; it envies not and is not puffed up.","theme":"marriage","when":"patience in marriage","mean":"God defines real love as patient and kind, so I let this love govern how I treat my spouse day by day."},{"id":"1-peter-3-7","ref":"1 Peter 3:7","kjv":"Likewise, ye husbands, dwell with them according to knowledge, giving honour unto the wife, as unto the weaker vessel, and as being heirs together of the grace of life; that your prayers be not hindered.","say":"I dwell with my wife according to knowledge, honouring her as a fellow heir of the grace of life, that my prayers be not hindered.","theme":"marriage","when":"how I treat my wife affects my walk with God","mean":"How I treat my spouse affects my fellowship with God, so I live with her in understanding and honour so nothing hinders my prayers."},{"id":"colossians-3-19","ref":"Colossians 3:19","kjv":"Husbands, love your wives, and be not bitter against them.","say":"I love my wife and refuse to grow bitter against her.","theme":"marriage","when":"resentment in conflict","mean":"God commands husbands to love without bitterness, so I release resentment and keep tenderness toward my wife even after offense."},{"id":"ecclesiastes-9-9","ref":"Ecclesiastes 9:9","kjv":"Live joyfully with the wife whom thou lovest all the days of the life of thy vanity, which he hath given thee under the sun, all the days of thy vanity: for that is thy portion in this life, and in thy labour which thou takest under the sun.","say":"I live joyfully with the spouse I love all the days God gives me under the sun.","theme":"marriage","when":"weary in marriage","mean":"God calls me to actively enjoy my marriage as His gift for this brief life, so I choose joy with my spouse rather than mere endurance."},{"id":"ephesians-5-25","ref":"Ephesians 5:25","kjv":"Husbands, love your wives, even as Christ also loved the church, and gave himself for it;","say":"I love my wife even as Christ loved the church and gave Himself for it.","theme":"marriage","when":"loving my wife sacrificially","mean":"Christ's self-giving is the measure of my love, so I lay down my own comfort and interests for my wife's good."},{"id":"ephesians-5-33","ref":"Ephesians 5:33","kjv":"Nevertheless let every one of you in particular so love his wife even as himself; and the wife see that she reverence her husband.","say":"I love my spouse as my own self, and we honour one another with love and reverence.","theme":"marriage","when":"mutual honour","mean":"God calls for love and reverence in marriage, so I cherish and honour my spouse as the Word commands."},{"id":"genesis-2-18","ref":"Genesis 2:18","kjv":"And the LORD God said, It is not good that the man should be alone; I will make him an help meet for him.","say":"God Himself said it is not good to be alone, and He has given me a help meet suited for me.","theme":"marriage","when":"valuing companionship in marriage","mean":"God designed marriage as partnership, so I honour my spouse as the companion He lovingly provided."},{"id":"genesis-2-24","ref":"Genesis 2:24","kjv":"Therefore shall a man leave his father and his mother, and shall cleave unto his wife: and they shall be one flesh.","say":"I leave every lesser tie to cleave to my spouse, for God has made us one flesh.","theme":"marriage","when":"protecting the covenant","mean":"God has joined us as one flesh, so I put my spouse above every other relationship and stay faithfully bound to them."},{"id":"hebrews-13-4","ref":"Hebrews 13:4","kjv":"Marriage is honourable in all, and the bed undefiled: but whoremongers and adulterers God will judge.","say":"I hold my marriage in honour and keep the marriage bed undefiled.","theme":"marriage","when":"guarding faithfulness","mean":"God declares marriage honourable and sacred, so I guard my fidelity and purity in reverence to Him."},{"id":"malachi-2-15","ref":"Malachi 2:15","kjv":"And did not he make one? Yet had he the residue of the spirit. And wherefore one? That he might seek a godly seed. Therefore take heed to your spirit, and let none deal treacherously against the wife of his youth.","say":"I take heed to my own spirit and deal faithfully, never treacherously, with the spouse of my youth.","theme":"marriage","when":"guarding my heart","mean":"God hates treachery in marriage, so I watch over my own spirit to stay loyal and true to my spouse."},{"id":"mark-10-9","ref":"Mark 10:9","kjv":"What therefore God hath joined together, let not man put asunder.","say":"What God has joined together in my marriage, I let no man put asunder.","theme":"marriage","when":"marriage under pressure","mean":"God Himself united my marriage, so I refuse to let any person, pressure, or circumstance divide what He has joined."},{"id":"proverbs-18-22","ref":"Proverbs 18:22","kjv":"Whoso findeth a wife findeth a good thing, and obtaineth favour of the LORD.","say":"In finding my spouse I have found a good thing, and I have obtained favour of the LORD.","theme":"marriage","when":"gratitude for my spouse","mean":"My marriage is a token of God's favour, so I receive my spouse with thanksgiving rather than taking them for granted."},{"id":"proverbs-19-14","ref":"Proverbs 19:14","kjv":"House and riches are the inheritance of fathers: and a prudent wife is from the LORD.","say":"My prudent spouse is a gift from the LORD Himself.","theme":"marriage","when":"gratitude for my spouse","mean":"A wise spouse is not merely earned but given by God, so I receive mine as His personal gift and steward them well."},{"id":"proverbs-31-10","ref":"Proverbs 31:10","kjv":"Who can find a virtuous woman? for her price is far above rubies.","say":"I treasure my virtuous spouse, whose worth to me is far above rubies.","theme":"marriage","when":"valuing my spouse","mean":"My spouse's godly character is of surpassing worth, so I cherish and esteem them instead of overlooking what I have been given."},{"id":"proverbs-5-18","ref":"Proverbs 5:18","kjv":"Let thy fountain be blessed: and rejoice with the wife of thy youth.","say":"My fountain is blessed, and I rejoice with the spouse of my youth.","theme":"marriage","when":"renewing romance","mean":"God blesses faithful marital love, so I keep my delight reserved for my own spouse and let our affection stay alive."},{"id":"psalm-128-3","ref":"Psalms 128:3","kjv":"Thy wife shall be as a fruitful vine by the sides of thine house: thy children like olive plants round about thy table.","say":"My wife is as a fruitful vine within my house, and my children like olive plants around my table.","theme":"marriage","when":"blessing over the home","mean":"God pictures a home full of life and fruitfulness for those who fear Him, so I give thanks for and nurture my family."},{"id":"song-of-solomon-2-16","ref":"Song of Solomon 2:16","kjv":"My beloved is mine, and I am his: he feedeth among the lilies.","say":"My beloved is mine, and I am my beloved's.","theme":"marriage","when":"belonging and intimacy","mean":"Covenant love is mutual belonging, so I give myself fully to my spouse and rest secure in being theirs."},{"id":"2-timothy-1-5","ref":"2 Timothy 1:5","kjv":"When I call to remembrance the unfeigned faith that is in thee, which dwelt first in thy grandmother Lois, and thy mother Eunice; and I am persuaded that in thee also.","say":"Like the unfeigned faith that dwelt first in Lois and Eunice, I live out a sincere faith for my children to inherit.","theme":"parenting","when":"building a legacy of faith","mean":"Genuine faith is handed down through generations by example, so I live out real faith for my children to receive."},{"id":"2-timothy-3-15","ref":"2 Timothy 3:15","kjv":"And that from a child thou hast known the holy scriptures, which are able to make thee wise unto salvation through faith which is in Christ Jesus.","say":"From a child my children know the holy scriptures, which are able to make them wise unto salvation through faith which is in Christ Jesus.","theme":"parenting","when":"teaching the Bible early","mean":"Scripture planted early makes my children wise toward salvation in Christ, so I give them God's Word from their youngest days."},{"id":"3-john-1-4","ref":"3 John 1:4","kjv":"I have no greater joy than to hear that my children walk in truth.","say":"I have no greater joy than to hear that my children walk in truth.","theme":"parenting","when":"longing for my kids to follow Christ","mean":"My deepest joy is my children living in God's truth, so my heart stays set on their walk with Him above every other good."},{"id":"acts-2-39","ref":"Acts 2:39","kjv":"For the promise is unto you, and to your children, and to all that are afar off, even as many as the Lord our God shall call.","say":"The promise is unto me and to my children, and to all that are afar off, even as many as the Lord our God shall call.","theme":"parenting","when":"claiming God's covenant for my kids","mean":"God's saving promise extends to my children by His own calling, so I pray and believe for them within His sovereign call."},{"id":"deuteronomy-6-7","ref":"Deuteronomy 6:7","kjv":"And thou shalt teach them diligently unto thy children, and shalt talk of them when thou sittest in thine house, and when thou walkest by the way, and when thou liest down, and when thou risest up.","say":"I teach God's words diligently to my children, talking of them when I sit in my house, when I walk by the way, when I lie down, and when I rise up.","theme":"parenting","when":"daily discipleship at home","mean":"Teaching faith is woven into ordinary daily life, so I make every part of the day a chance to point my children to God."},{"id":"ephesians-6-4","ref":"Ephesians 6:4","kjv":"And, ye fathers, provoke not your children to wrath: but bring them up in the nurture and admonition of the Lord.","say":"I do not provoke my children to wrath, but bring them up in the nurture and admonition of the Lord.","theme":"parenting","when":"frustrated with my kids","mean":"I am called to parent without harshness that embitters, raising them with the Lord's own loving correction and instruction."},{"id":"genesis-18-19","ref":"Genesis 18:19","kjv":"For I know him, that he will command his children and his household after him, and they shall keep the way of the LORD, to do justice and judgment; that the LORD may bring upon Abraham that which he hath spoken of him.","say":"Like Abraham, I command my children and my household after me to keep the way of the LORD, to do justice and judgment.","theme":"parenting","when":"leading my household in righteousness","mean":"God honored Abraham for intentionally directing his family in God's ways, and I take up that same charge to lead mine in righteousness and justice."},{"id":"isaiah-44-3","ref":"Isaiah 44:3","kjv":"For I will pour water upon him that is thirsty, and floods upon the dry ground: I will pour my spirit upon thy seed, and my blessing upon thine offspring:","say":"I ask God in faith to pour out His Spirit upon my seed and His blessing upon my offspring.","theme":"parenting","when":"praying the Spirit over my children","mean":"God's covenant promise is to pour His own Spirit and blessing on offspring, so I bring my children before Him and ask for it in faith."},{"id":"isaiah-54-13","ref":"Isaiah 54:13","kjv":"And all thy children shall be taught of the LORD; and great shall be the peace of thy children.","say":"My children shall be taught of the LORD, and great shall be their peace.","theme":"parenting","when":"worried about their future","mean":"God Himself teaches His people's children and gives them deep peace, so I entrust my children's hearts to Him."},{"id":"joshua-24-15","ref":"Joshua 24:15","kjv":"And if it seem evil unto you to serve the LORD, choose you this day whom ye will serve; whether the gods which your fathers served that were on the other side of the flood, or the gods of the Amorites, in whose land ye dwell: but as for me and my house, we will serve the LORD.","say":"As for me and my house, we will serve the LORD.","theme":"parenting","when":"setting the tone for my home","mean":"I take responsibility to lead my household in wholehearted devotion to God, whatever others around me choose."},{"id":"mark-10-14","ref":"Mark 10:14","kjv":"But when Jesus saw it, he was much displeased, and said unto them, Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God.","say":"I bring my little children to Jesus and do not hinder them, for of such is the kingdom of God.","theme":"parenting","when":"bringing my kids to Christ","mean":"Jesus welcomes children gladly and is displeased when they are kept from Him, so I bring mine to Him and let nothing hinder them."},{"id":"proverbs-20-7","ref":"Proverbs 20:7","kjv":"The just man walketh in his integrity: his children are blessed after him.","say":"I walk in my integrity, and my children are blessed after me.","theme":"parenting","when":"living right for my children's sake","mean":"My own upright walk leaves a blessing my children inherit, so my daily integrity is itself a gift to them."},{"id":"proverbs-22-6","ref":"Proverbs 22:6","kjv":"Train up a child in the way he should go: and when he is old, he will not depart from it.","say":"I train up my children in the way they should go, and when they are old they will not depart from it.","theme":"parenting","when":"raising young children","mean":"God calls me to set my children on His path early and trust that this foundation will hold through their lives."},{"id":"proverbs-29-17","ref":"Proverbs 29:17","kjv":"Correct thy son, and he shall give thee rest; yea, he shall give delight unto thy soul.","say":"I correct my son, and he gives me rest; he gives delight unto my soul.","theme":"parenting","when":"weary of disciplining","mean":"Loving, consistent correction is not wasted but yields peace and delight, so I keep disciplining faithfully, expecting good fruit."},{"id":"proverbs-31-28","ref":"Proverbs 31:28","kjv":"Her children arise up, and call her blessed; her husband also, and he praiseth her.","say":"My children arise up and call me blessed, and my household honors me.","theme":"parenting","when":"feeling unseen as a parent","mean":"Faithful, godly parenting bears the fruit of children who honor and bless me, so I pour myself out knowing God sees and it will be honored."},{"id":"psalm-103-17","ref":"Psalms 103:17","kjv":"But the mercy of the LORD is from everlasting to everlasting upon them that fear him, and his righteousness unto children’s children;","say":"The mercy of the LORD is from everlasting upon them that fear Him, and His righteousness reaches unto my children's children.","theme":"parenting","when":"trusting God for my grandchildren","mean":"God's mercy and righteousness run through generations to my children's children, so I fear Him, resting in His covenant love over my line."},{"id":"psalm-127-3","ref":"Psalms 127:3","kjv":"Lo, children are an heritage of the LORD: and the fruit of the womb is his reward.","say":"My children are an heritage of the LORD, and the fruit of the womb is His reward.","theme":"parenting","when":"overwhelmed parent","mean":"My children are not a burden but a God-given inheritance and reward, so I receive and steward them with gratitude."},{"id":"psalm-78-4","ref":"Psalms 78:4","kjv":"We will not hide them from their children, shewing to the generation to come the praises of the LORD, and his strength, and his wonderful works that he hath done.","say":"I will not hide the LORD's works from my children, but show the generation to come His praises, His strength, and His wonderful works.","theme":"parenting","when":"passing on the testimony","mean":"I am a storyteller of God's mighty acts to the next generation, keeping His praise alive in my family's memory."},{"id":"1-peter-5-7","ref":"1 Peter 5:7","kjv":"Casting all your care upon him; for he careth for you.","say":"I cast all my care upon Him, for He careth for me.","theme":"peace-anxiety","when":"carrying heavy worry","mean":"I hand every care over to God because the burden is not mine to carry alone; He actively cares for me, so casting it on Him is trust, not avoidance."},{"id":"2-thessalonians-3-16","ref":"2 Thessalonians 3:16","kjv":"Now the Lord of peace himself give you peace always by all means. The Lord be with you all.","say":"The Lord of peace Himself gives me His peace at all times and in every way; the Lord is with me.","theme":"peace-anxiety","when":"Needing peace in every area","mean":"Peace is the gift of the Lord of peace Himself, promised at all times and by every means, grounded in His abiding presence with me."},{"id":"2-timothy-1-7","ref":"2 Timothy 1:7","kjv":"For God hath not given us the spirit of fear; but of power, and of love, and of a sound mind.","say":"God has not given me the spirit of fear, but of power, and of love, and of a sound mind.","theme":"peace-anxiety","when":"Panic or a fearful spirit","mean":"Fear is not from God, so I refuse it and take hold of what His Spirit did give me: power, love, and a sound, self-controlled mind."},{"id":"colossians-3-15","ref":"Colossians 3:15","kjv":"And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.","say":"I let the peace of God rule in my heart, to which I am called; and I will be thankful.","theme":"peace-anxiety","when":"Unsettled and needing inner government","mean":"I let God's peace act as the umpire over my inner life, the peace I was called into, and thanksgiving keeps that peace on the throne."},{"id":"isaiah-26-3","ref":"Isaiah 26:3","kjv":"Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.","say":"The LORD keeps me in perfect peace, because my mind is stayed on Him and I trust in Him.","theme":"peace-anxiety","when":"anxious or overwhelmed","mean":"Peace comes as I deliberately fix my thoughts on God rather than my fears; the keeping is His part, the staying of my mind is mine."},{"id":"john-14-27","ref":"John 14:27","kjv":"Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.","say":"I receive the peace Christ gives me, not as the world gives; I will not let my heart be troubled, neither will I be afraid.","theme":"peace-anxiety","when":"a troubled, fearful heart","mean":"Jesus leaves me a peace the world cannot manufacture or take away, and He invites me to actively refuse a troubled, fearful heart because His peace is already given."},{"id":"john-16-33","ref":"John 16:33","kjv":"These things I have spoken unto you, that in me ye might have peace. In the world ye shall have tribulation: but be of good cheer; I have overcome the world.","say":"In Christ I have peace; though in the world I have tribulation, I am of good cheer, for He has overcome the world.","theme":"peace-anxiety","when":"in tribulation","mean":"Jesus is honest that tribulation will come, yet He anchors my peace and good cheer in His own finished victory over the world, so I can be troubled by circumstances without being conquered by them."},{"id":"matthew-11-28","ref":"Matthew 11:28","kjv":"Come unto me, all ye that labour and are heavy laden, and I will give you rest.","say":"I come to Jesus with all my labour and heavy burden, and He gives me rest.","theme":"peace-anxiety","when":"weary or burned out","mean":"The exhausted and overloaded are exactly whom Jesus invites; coming to Him, not pushing harder, is where real rest for the soul is found."},{"id":"matthew-6-34","ref":"Matthew 6:34","kjv":"Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.","say":"I take no anxious thought for the morrow, for tomorrow will take thought for itself; I trust God with the day I am in, for today's own trouble is enough for today.","theme":"peace-anxiety","when":"Worried about the future","mean":"Jesus tells me to live in today and leave tomorrow to God; borrowing tomorrow's troubles only doubles a weight He never asked me to carry, for each day has trouble enough of its own."},{"id":"philippians-4-6","ref":"Philippians 4:6","kjv":"Be careful for nothing; but in every thing by prayer and supplication with thanksgiving let your requests be made known unto God.","say":"I am careful for nothing, but in every thing, by prayer and supplication with thanksgiving, I make my requests known unto God.","theme":"peace-anxiety","when":"anxious or worried","mean":"Worry is answered not by willpower but by taking every single concern to God in thankful prayer, so I replace anxious rehearsing with honest asking ('careful' here means anxious)."},{"id":"philippians-4-7","ref":"Philippians 4:7","kjv":"And the peace of God, which passeth all understanding, shall keep your hearts and minds through Christ Jesus.","say":"The peace of God, which passeth all understanding, keeps my heart and mind through Christ Jesus.","theme":"peace-anxiety","when":"a racing, overwhelmed mind","mean":"When I pray instead of worry (v.6), God Himself guards my heart and thoughts with a peace that outruns my ability to explain it, kept in Christ."},{"id":"psalm-112-7","ref":"Psalms 112:7","kjv":"He shall not be afraid of evil tidings: his heart is fixed, trusting in the LORD.","say":"I will not be afraid of evil tidings; my heart is fixed, trusting in the LORD.","theme":"peace-anxiety","when":"Dreading bad news","mean":"A heart anchored in the LORD can receive even bad news unshaken, because its stability rests on settled trust rather than on favourable reports."},{"id":"psalm-34-4","ref":"Psalms 34:4","kjv":"I sought the LORD, and he heard me, and delivered me from all my fears.","say":"I sought the LORD, and He heard me, and He delivered me from all my fears.","theme":"peace-anxiety","when":"Gripped by fear","mean":"Seeking the LORD is never in vain; He hears me and delivers me from all my fears, not merely some, as I keep turning to Him."},{"id":"psalm-55-22","ref":"Psalms 55:22","kjv":"Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.","say":"I cast my burden upon the LORD, and He sustains me; He will never suffer me to be moved.","theme":"peace-anxiety","when":"Overwhelmed and pressed down by cares","mean":"When I roll the weight of my cares onto the LORD, He Himself takes up the carrying of me; the one who trusts Him is held steady and kept from being shaken."},{"id":"psalm-94-19","ref":"Psalms 94:19","kjv":"In the multitude of my thoughts within me thy comforts delight my soul.","say":"In the multitude of my anxious thoughts within me, Thy comforts delight my soul.","theme":"peace-anxiety","when":"Anxious thoughts crowding in","mean":"When disquieting thoughts pile up inside me, God's comforts meet me in the crowd and bring genuine delight to my soul."},{"id":"psalms-27-1","ref":"Psalms 27:1","kjv":"The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?","say":"The LORD is my light and my salvation, and the strength of my life; whom shall I fear, and of whom shall I be afraid?","theme":"peace-anxiety","when":"afraid in the face of a health crisis","mean":"Because the LORD Himself is my light, salvation, and strength, fear over my circumstances has no rightful hold on me."},{"id":"2-timothy-2-3","ref":"2 Timothy 2:3","kjv":"Thou therefore endure hardness, as a good soldier of Jesus Christ.","say":"I endure hardness as a good soldier of Jesus Christ.","theme":"perseverance-waiting","when":"hardship in ministry or calling","mean":"A soldier expects difficulty and does not resent it; I accept hardship as part of serving Christ, staying disciplined and loyal to my Commander through it."},{"id":"galatians-6-9","ref":"Galatians 6:9","kjv":"And let us not be weary in well doing: for in due season we shall reap, if we faint not.","say":"I will not be weary in well doing, for in due season I shall reap if I faint not.","theme":"perseverance-waiting","when":"doing good with no visible reward yet","mean":"Doing right often feels unrewarded for a long time, but God keeps a harvest schedule; my job is to keep sowing good and not collapse before the season God has set."},{"id":"habakkuk-2-3","ref":"Habakkuk 2:3","kjv":"For the vision is yet for an appointed time, but at the end it shall speak, and not lie: though it tarry, wait for it; because it will surely come, it will not tarry.","say":"Though the vision tarry, I wait for it; for it is for an appointed time, and it will surely come and not tarry.","theme":"perseverance-waiting","when":"a God-given vision is delayed","mean":"God's promises run on His appointed time, not mine; a delay is not a denial, so I keep waiting on a vision He has guaranteed will come."},{"id":"hebrews-10-36","ref":"Hebrews 10:36","kjv":"For ye have need of patience, that, after ye have done the will of God, ye might receive the promise.","say":"I have need of patience, that after I have done the will of God, I might receive the promise.","theme":"perseverance-waiting","when":"obeyed God but still waiting on the promise","mean":"Obedience and the promised outcome are often separated by a stretch of waiting; patience is what carries me across that gap so I actually receive what God pledged."},{"id":"hebrews-12-1","ref":"Hebrews 12:1","kjv":"Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,","say":"I lay aside every weight and the sin that so easily besets me, and I run with patience the race that is set before me.","theme":"perseverance-waiting","when":"weary and weighed down","mean":"My race is specific and set before me, so I drop what slows me and run it with patient endurance rather than frantic haste."},{"id":"james-1-12","ref":"James 1:12","kjv":"Blessed is the man that endureth temptation: for when he is tried, he shall receive the crown of life, which the Lord hath promised to them that love him.","say":"Blessed am I when I endure temptation, for when I am tried I shall receive the crown of life, which the Lord hath promised to them that love Him.","theme":"perseverance-waiting","when":"under trial and temptation","mean":"Enduring trial is not merely survival; it is the path to a promised reward, so I hold fast under testing out of love for the One who crowns the faithful."},{"id":"james-1-3","ref":"James 1:3","kjv":"Knowing this, that the trying of your faith worketh patience.","say":"I know that the trying of my faith worketh patience.","theme":"perseverance-waiting","when":"faith being tested","mean":"Trials are not God abandoning me; they are the very process He uses to produce endurance in me, so I meet testing as a workshop rather than a verdict."},{"id":"james-5-7","ref":"James 5:7","kjv":"Be patient therefore, brethren, unto the coming of the Lord. Behold, the husbandman waiteth for the precious fruit of the earth, and hath long patience for it, until he receive the early and latter rain.","say":"I am patient like the husbandman who waits for the precious fruit of the earth, with long patience until the early and latter rain.","theme":"perseverance-waiting","when":"waiting on a slow harvest","mean":"A farmer cannot rush a harvest; he works and waits through the seasons, and so I patiently trust God's timing for the fruit He has promised to bring."},{"id":"lamentations-3-26","ref":"Lamentations 3:26","kjv":"It is good that a man should both hope and quietly wait for the salvation of the LORD.","say":"It is good that I should both hope and quietly wait for the salvation of the LORD.","theme":"perseverance-waiting","when":"in the dark, waiting for rescue","mean":"Even in deep trouble, quiet hopeful waiting on God is itself a good and right posture; I don't force the outcome, I settle into expectant stillness before Him."},{"id":"micah-7-7","ref":"Micah 7:7","kjv":"Therefore I will look unto the LORD; I will wait for the God of my salvation: my God will hear me.","say":"I look unto the LORD; I wait for the God of my salvation, and my God hears me.","theme":"perseverance-waiting","when":"surrounded by trouble, waiting on God to act","mean":"When people and circumstances fail me, I deliberately turn my eyes to God and wait, confident that the God of my salvation hears and will act."},{"id":"psalms-27-14","ref":"Psalms 27:14","kjv":"Wait on the LORD: be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD.","say":"I wait on the LORD and am of good courage, and He strengthens my heart; I wait, I say, on the LORD.","theme":"perseverance-waiting","when":"discouraged while waiting","mean":"Waiting on God is not passive drifting but courageous trust; as I keep waiting, He Himself puts fresh strength into my heart."},{"id":"psalms-37-7","ref":"Psalms 37:7","kjv":"Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass.","say":"I rest in the LORD and wait patiently for Him; I fret not myself because of the man who prospers in his wicked ways.","theme":"perseverance-waiting","when":"the wicked seem to get ahead while I wait","mean":"Watching the unrighteous flourish tempts me to anxiety and envy, but I quiet my heart in God and let Him deal with outcomes in His own time."},{"id":"psalms-40-1","ref":"Psalms 40:1","kjv":"I waited patiently for the LORD; and he inclined unto me, and heard my cry.","say":"I wait patiently for the LORD, and He inclines unto me and hears my cry.","theme":"perseverance-waiting","when":"crying out, awaiting God's answer","mean":"David's rescue came after patient waiting; my cry is not lost in the delay, for the LORD bends down to hear and answers in His time."},{"id":"romans-8-25","ref":"Romans 8:25","kjv":"But if we hope for that we see not, then do we with patience wait for it.","say":"I hope for what I do not yet see, and so with patience I wait for it.","theme":"perseverance-waiting","when":"hoping for the unseen","mean":"Biblical hope is for what is not yet visible, and patience is simply hope holding on; I wait steadily for what God has promised but I cannot yet see."},{"id":"1-john-5-14","ref":"1 John 5:14","kjv":"And this is the confidence that we have in him, that, if we ask any thing according to his will, he heareth us:","say":"This is my confidence: when I ask anything according to His will, my God hears me.","theme":"prayer","when":"wondering if God hears","mean":"My assurance rests not on my feelings but on God's promise to hear prayers that align with His will, so I pray His word back to Him."},{"id":"1-peter-3-12","ref":"1 Peter 3:12","kjv":"For the eyes of the Lord are over the righteous, and his ears are open unto their prayers: but the face of the Lord is against them that do evil.","say":"The eyes of the Lord are over me, and His ears are open unto my prayers.","theme":"prayer","when":"wondering if God is listening","mean":"In Christ, God's attention and open ear are turned toward me, so I pray knowing I am seen and heard by a watchful Father."},{"id":"1-thessalonians-5-17","ref":"1 Thessalonians 5:17","kjv":"Pray without ceasing.","say":"I pray without ceasing, keeping an open line of fellowship with my God all day long.","theme":"prayer","when":"building a prayer life","mean":"Prayer is not only an event but a continual walk with God, so I keep my heart turned toward Him through the ordinary hours."},{"id":"isaiah-65-24","ref":"Isaiah 65:24","kjv":"And it shall come to pass, that before they call, I will answer; and while they are yet speaking, I will hear.","say":"Before I call, my God answers; while I am yet speaking, He hears.","theme":"prayer","when":"waiting on an answer","mean":"God is already moving on my behalf before my prayer is even finished, so I wait on Him with hope rather than despair."},{"id":"james-5-16","ref":"James 5:16","kjv":"Confess your faults one to another, and pray one for another, that ye may be healed. The effectual fervent prayer of a righteous man availeth much.","say":"Because I am made righteous in Christ, my effectual fervent prayer availeth much.","theme":"prayer","when":"interceding for others","mean":"I am declared righteous through Jesus, so my earnest, Spirit-led prayer carries real power as I stand in the gap for others."},{"id":"john-15-7","ref":"John 15:7","kjv":"If ye abide in me, and my words abide in you, ye shall ask what ye will, and it shall be done unto you.","say":"As I abide in Christ and His words abide in me, I ask what I will, and it is done.","theme":"prayer","when":"abiding in Christ","mean":"Answered prayer flows from a life rooted in Jesus and shaped by His word, so I stay connected to Him and let His word reshape what I ask for."},{"id":"luke-18-1","ref":"Luke 18:1","kjv":"And he spake a parable unto them to this end, that men ought always to pray, and not to faint;","say":"I ought always to pray and not to faint; I keep bringing my requests to God and will not lose heart.","theme":"prayer","when":"tempted to give up praying","mean":"In the parable of the persistent widow, Jesus teaches me to keep praying rather than lose heart, trusting a just God who answers His own in due time."},{"id":"mark-11-24","ref":"Mark 11:24","kjv":"Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them.","say":"When I pray, I believe that I receive, and I rest in my Father's faithfulness.","theme":"prayer","when":"believing for an answer","mean":"I pray with genuine faith, trusting God's goodness and timing rather than demanding my own terms, holding my requests before Him believing."},{"id":"matthew-7-7","ref":"Matthew 7:7","kjv":"Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:","say":"I ask, and it is given me; I seek, and I find; I knock, and it is opened unto me.","theme":"prayer","when":"persevering in prayer","mean":"Jesus commands a persistent posture of asking, seeking, and knocking, and promises that such praying is never wasted."},{"id":"psalm-116-1","ref":"Psalms 116:1","kjv":"I love the LORD, because he hath heard my voice and my supplications.","say":"I love the Lord, because He has heard my voice and my supplications.","theme":"prayer","when":"grateful that God heard my prayer","mean":"Remembering that God has heard and answered deepens my love for Him and strengthens my confidence to keep calling on Him."},{"id":"psalm-145-18","ref":"Psalms 145:18","kjv":"The LORD is nigh unto all them that call upon him, to all that call upon him in truth.","say":"The Lord is near to me as I call upon Him in truth.","theme":"prayer","when":"feeling far from God","mean":"Even when God feels distant, His promise is that He draws near to everyone who calls on Him sincerely, so I call out honestly."},{"id":"psalm-34-17","ref":"Psalms 34:17","kjv":"The righteous cry, and the LORD heareth, and delivereth them out of all their troubles.","say":"When I cry, the Lord hears me and delivers me out of all my troubles.","theme":"prayer","when":"in distress","mean":"God does not ignore the cry of His people; He bends to hear and acts to deliver, so I bring my troubles to Him honestly."},{"id":"psalm-55-17","ref":"Psalms 55:17","kjv":"Evening, and morning, and at noon, will I pray, and cry aloud: and he shall hear my voice.","say":"Evening, morning, and at noon I pray and cry aloud, and He hears my voice.","theme":"prayer","when":"daily prayer discipline","mean":"I set rhythms of prayer through my day, bringing my voice to God again and again, confident that He hears each time."},{"id":"psalm-66-19","ref":"Psalms 66:19","kjv":"But verily God hath heard me; he hath attended to the voice of my prayer.","say":"Truly God has heard me; He has attended to the voice of my prayer.","theme":"prayer","when":"assurance after praying","mean":"I can rise from prayer settled in confidence, declaring that God has genuinely heard and attended to what I brought Him."},{"id":"romans-8-26","ref":"Romans 8:26","kjv":"Likewise the Spirit also helpeth our infirmities: for we know not what we should pray for as we ought: but the Spirit itself maketh intercession for us with groanings which cannot be uttered.","say":"When I know not what to pray, the Spirit Himself helps my weakness and makes intercession for me.","theme":"prayer","when":"weary, with no words to pray","mean":"Even when I am too weak to form the words, the Holy Spirit carries my prayer to the Father, so my feeble praying is never alone."},{"id":"2-thessalonians-3-3","ref":"2 Thessalonians 3:3","kjv":"But the Lord is faithful, who shall stablish you, and keep you from evil.","say":"The Lord is faithful; He establishes me and keeps me from evil.","theme":"protection-safety","when":"Under spiritual attack or pressing temptation","mean":"Because God Himself is faithful, He steadies me and guards me from the evil one; my security rests on His faithfulness and not on my own strength."},{"id":"2-timothy-1-12","ref":"2 Timothy 1:12","kjv":"For the which cause I also suffer these things: nevertheless I am not ashamed: for I know whom I have believed, and am persuaded that he is able to keep that which I have committed unto him against that day.","say":"I know whom I have believed, and I am persuaded that He is able to keep what I have committed to Him against that day.","theme":"protection-safety","when":"Facing an uncertain future and entrusting what I cannot control","mean":"Paul, in chains, rested on Christ's power to guard all he had entrusted to Him; whatever I commit to God, He is able to keep safe to the very last day."},{"id":"deuteronomy-33-27","ref":"Deuteronomy 33:27","kjv":"The eternal God is thy refuge, and underneath are the everlasting arms: and he shall thrust out the enemy from before thee; and shall say, Destroy them.","say":"The eternal God is my refuge, and underneath me are the everlasting arms; He thrusts out the enemy before me.","theme":"protection-safety","when":"Exhausted and feeling like I will fall","mean":"However low I sink, I never fall below God's everlasting arms; the eternal One Himself holds me up and drives back whatever comes against me."},{"id":"john-10-28","ref":"John 10:28","kjv":"And I give unto them eternal life; and they shall never perish, neither shall any man pluck them out of my hand.","say":"I have eternal life in Christ; I shall never perish, and no one can pluck me out of His hand.","theme":"protection-safety","when":"Fearing I could be lost, longing for assurance","mean":"Jesus Himself holds His sheep; no power and no person can snatch me from His grip, so my eternal security rests in His hand and not in my own."},{"id":"nahum-1-7","ref":"Nahum 1:7","kjv":"The LORD is good, a strong hold in the day of trouble; and he knoweth them that trust in him.","say":"The LORD is good, my stronghold in the day of trouble, and He knows me because I trust in Him.","theme":"protection-safety","when":"In a hard season, a real day of trouble","mean":"Even set within a prophecy of judgment, this verse is grace to those who trust Him: God is good, He is my stronghold, and He personally knows the ones who run to Him."},{"id":"proverbs-18-10","ref":"Proverbs 18:10","kjv":"The name of the LORD is a strong tower: the righteous runneth into it, and is safe.","say":"The name of the LORD is my strong tower; I run into it and I am safe.","theme":"protection-safety","when":"A sudden crisis or rush of panic","mean":"When danger strikes, my first move is to call on who the LORD is and take shelter in His name, set high above every threat; that is where true safety is found."},{"id":"psalm-121-7-8","ref":"Psalms 121:7-8","kjv":"The LORD shall preserve thee from all evil: he shall preserve thy soul. The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.","say":"The LORD preserves me from all evil; He preserves my soul, my going out and my coming in, from this time forth and for evermore.","theme":"protection-safety","when":"daily comings and goings or commute","mean":"God's protection covers my whole life and every journey, not just emergencies; He guards both my body's path and my inner soul continually."},{"id":"psalm-3-3","ref":"Psalms 3:3","kjv":"But thou, O LORD, art a shield for me; my glory, and the lifter up of mine head.","say":"You, O LORD, are a shield for me, my glory and the lifter up of my head.","theme":"protection-safety","when":"surrounded by trouble or discouraged","mean":"David prayed this while fleeing enemies; God not only defends me but restores my dignity and lifts my head when I am beaten down."},{"id":"psalm-32-7","ref":"Psalms 32:7","kjv":"Thou art my hiding place; thou shalt preserve me from trouble; thou shalt compass me about with songs of deliverance. Selah.","say":"You are my hiding place; You preserve me from trouble and surround me with songs of deliverance.","theme":"protection-safety","when":"Needing shelter when fear closes in","mean":"I run to God as my hiding place, and He does more than shield me from trouble; He surrounds me with a deliverance I will one day sing about."},{"id":"psalm-34-7","ref":"Psalms 34:7","kjv":"The angel of the LORD encampeth round about them that fear him, and delivereth them.","say":"The angel of the LORD encamps round about me because I fear Him, and He delivers me.","theme":"protection-safety","when":"feeling vulnerable or traveling","mean":"God sets a guard of His own around those who reverence Him; I am not alone or unprotected, even when I feel exposed."},{"id":"psalm-4-8","ref":"Psalms 4:8","kjv":"I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.","say":"I will lie down in peace and sleep, for You alone, LORD, make me dwell in safety.","theme":"protection-safety","when":"Unable to sleep because of night fears","mean":"I can rest at night because my safety rests on the LORD alone and not on my own watchfulness; I hand the night to Him and sleep."},{"id":"psalm-91-1-2","ref":"Psalms 91:1-2","kjv":"He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty. I will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.","say":"I dwell in the secret place of the Most High and abide under the shadow of the Almighty; the LORD is my refuge and my fortress, my God, and in Him will I trust.","theme":"protection-safety","when":"afraid or under threat","mean":"Safety is found in staying close to God in prayer and trust, not in my circumstances; I make Him my hiding place and rest under His cover."},{"id":"psalm-91-11","ref":"Psalms 91:11","kjv":"For he shall give his angels charge over thee, to keep thee in all thy ways.","say":"God gives His angels charge over me, to keep me in all my ways.","theme":"protection-safety","when":"Walking through risk, or covering those I love","mean":"God assigns angelic guardians to keep me as I walk in His ways; this is His promise to the one who abides in Him, never a license to presume on Him."},{"id":"psalms-125-2","ref":"Psalms 125:2","kjv":"As the mountains are round about Jerusalem, so the LORD is round about his people from henceforth even for ever.","say":"As the mountains stand round about Jerusalem, so the LORD is round about me, His child, from this time forth and for ever.","theme":"protection-safety","when":"feeling surrounded by problems","mean":"God encircles His people as permanently and immovably as mountains encircle a city; I am enclosed by the LORD Himself, forever."},{"id":"zechariah-2-5","ref":"Zechariah 2:5","kjv":"For I, saith the LORD, will be unto her a wall of fire round about, and will be the glory in the midst of her.","say":"The LORD Himself is a wall of fire around me and the glory in my midst.","theme":"protection-safety","when":"Feeling defenseless, with no covering","mean":"God promises to be both my defense without and my glory within; as one of His own, I lean on His surrounding fire rather than on walls I could build."},{"id":"1-timothy-6-17-18","ref":"1 Timothy 6:17-18","kjv":"Charge them that are rich in this world, that they be not highminded, nor trust in uncertain riches, but in the living God, who giveth us richly all things to enjoy; That they do good, that they be rich in good works, ready to distribute, willing to communicate;","say":"I trust not in uncertain riches but in the living God, who gives me richly all things to enjoy; and I am ready to do good, to distribute, and to share.","theme":"provision-finances","when":"I have increase; guarding my heart","mean":"God richly provides for my enjoyment, yet my trust rests in Him and not in money, and whatever He adds is for doing good and sharing freely."},{"id":"2-chronicles-26-5","ref":"2 Chronicles 26:5","kjv":"And he sought God in the days of Zechariah, who had understanding in the visions of God: and as long as he sought the LORD, God made him to prosper.","say":"As long as I seek the LORD, God makes me to prosper.","theme":"provision-finances","when":"long-haul faithfulness in seeking God","mean":"Uzziah prospered exactly as long as he sought God; so I keep seeking the LORD, knowing lasting increase flows from staying close to Him, not from the increase itself."},{"id":"2-corinthians-9-10","ref":"2 Corinthians 9:10","kjv":"Now he that ministereth seed to the sower both minister bread for your food, and multiply your seed sown, and increase the fruits of your righteousness;)","say":"God supplies both bread for my food and seed for my sowing; He multiplies my seed and increases the harvest of my righteousness, so I abound in generosity.","theme":"provision-finances","when":"a giver who fears being left empty","mean":"God supplies both my daily bread and extra seed to give, and multiplies it for more sowing, so my generosity never leaves me empty; He replenishes the giver for the fruit of righteousness, not personal gain."},{"id":"2-corinthians-9-8","ref":"2 Corinthians 9:8","kjv":"And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:","say":"God is able to make all grace abound toward me, so that having all sufficiency in all things, I abound unto every good work.","theme":"provision-finances","when":"stretched thin yet called to keep giving","mean":"God's grace gives me more than enough, not to hoard but to overflow in generosity and good works, so I can give freely without fear of lack."},{"id":"deuteronomy-2-7","ref":"Deuteronomy 2:7","kjv":"For the LORD thy God hath blessed thee in all the works of thy hand: he knoweth thy walking through this great wilderness: these forty years the LORD thy God hath been with thee; thou hast lacked nothing.","say":"The LORD my God has blessed the work of my hands and walked with me through the wilderness; He knows my journey, and under His care I have lacked nothing.","theme":"provision-finances","when":"a long, dry season of labor","mean":"Looking back over the hard miles, I testify that God was with me the whole way and I never truly lacked, and I trust that same faithfulness forward."},{"id":"deuteronomy-8-18","ref":"Deuteronomy 8:18","kjv":"But thou shalt remember the LORD thy God: for it is he that giveth thee power to get wealth, that he may establish his covenant which he sware unto thy fathers, as it is this day.","say":"I remember the LORD my God, for it is He who gives me power to get wealth, that He may establish His covenant.","theme":"provision-finances","when":"building a business or earning","mean":"Even my ability to earn is God-given and meant to serve His purposes, so I stay humble and credit Him for every increase rather than my own strength."},{"id":"ecclesiastes-5-19","ref":"Ecclesiastes 5:19","kjv":"Every man also to whom God hath given riches and wealth, and hath given him power to eat thereof, and to take his portion, and to rejoice in his labour; this is the gift of God.","say":"God has given me power to enjoy what He provides and to rejoice in my labour; this is the gift of God.","theme":"provision-finances","when":"guilt about enjoying provision","mean":"Not only the provision but the very capacity to enjoy it and delight in my work is God's gift, so I receive His supply with gratitude instead of guilt."},{"id":"genesis-22-14","ref":"Genesis 22:14","kjv":"And Abraham called the name of that place Jehovah-jireh: as it is said to this day, In the mount of the LORD it shall be seen.","say":"I call my God Jehovah-Jireh, the LORD who provides; in the place of my testing He Himself will see my need and provide.","theme":"provision-finances","when":"waiting for a provision I can't yet see","mean":"Like Abraham on the mountain where God provided the ram, I trust that at the very place of my testing the LORD sees and provides at the right moment."},{"id":"genesis-39-3","ref":"Genesis 39:3","kjv":"And his master saw that the LORD was with him, and that the LORD made all that he did to prosper in his hand.","say":"The LORD is with me in my work, and He makes all that I do to prosper in my hand.","theme":"provision-finances","when":"unseen faithfulness in a hard job","mean":"Like Joseph serving in another man's house, God's presence is what prospers my work, even before any promotion; so I stay faithful right where I am and trust Him with the increase."},{"id":"isaiah-33-16","ref":"Isaiah 33:16","kjv":"He shall dwell on high: his place of defence shall be the munitions of rocks: bread shall be given him; his waters shall be sure.","say":"I dwell on high; the LORD is my place of defence. My bread shall be given me, and my waters shall be sure.","theme":"provision-finances","when":"fear of scarcity, basic needs","mean":"To the one who walks uprightly (v.15) God guarantees shelter on high and the basics, bread and water, so I can rest in His sure supply in hard times."},{"id":"luke-6-38","ref":"Luke 6:38","kjv":"Give, and it shall be given unto you; good measure, pressed down, and shaken together, and running over, shall men give into your bosom. For with the same measure that ye mete withal it shall be measured to you again.","say":"I give, and it is given to me again; good measure, pressed down, shaken together, and running over.","theme":"provision-finances","when":"deciding whether to give; generosity","mean":"In its setting of mercy and open-handed giving, Jesus promises that a generous life is met with God's generous return, measured back in the same spirit I measure out to others."},{"id":"matthew-6-26","ref":"Matthew 6:26","kjv":"Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?","say":"My heavenly Father feeds the birds of the air, and because I am worth far more than they, I trust Him to provide for me and refuse to be anxious.","theme":"provision-finances","when":"anxious about tomorrow and daily needs","mean":"If God feeds birds that neither sow nor store, how much more will He care for me, His own child; so I lay down worry and rest in His provision."},{"id":"matthew-6-33","ref":"Matthew 6:33","kjv":"But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.","say":"I seek first the kingdom of God and His righteousness, and all these things are added unto me.","theme":"provision-finances","when":"money stress, wrong priorities","mean":"When I put God's kingdom first instead of chasing provision, He takes responsibility to add what I need."},{"id":"nehemiah-9-21","ref":"Nehemiah 9:21","kjv":"Yea, forty years didst thou sustain them in the wilderness, so that they lacked nothing; their clothes waxed not old, and their feet swelled not.","say":"God sustains me through my wilderness so that I lack nothing, and what He provides does not wear out before my journey ends.","theme":"provision-finances","when":"the long haul of sustained need","mean":"As God carried Israel through forty years without their supply failing, I trust Him to sustain me through long seasons so that His provision outlasts my need."},{"id":"philippians-4-19","ref":"Philippians 4:19","kjv":"But my God shall supply all your need according to his riches in glory by Christ Jesus.","say":"My God shall supply all my need according to His riches in glory by Christ Jesus.","theme":"provision-finances","when":"financial pressure","mean":"God pledges to meet my genuine need, out of His limitless riches, in Christ, so I can work and trust without panic."},{"id":"proverbs-10-22","ref":"Proverbs 10:22","kjv":"The blessing of the LORD, it maketh rich, and he addeth no sorrow with it.","say":"The blessing of the LORD is what makes me rich, and He adds no sorrow with it.","theme":"provision-finances","when":"striving or anxious about money","mean":"What God blesses comes clean, without the grief that anxious striving or ill-gotten gain carries, so I rest in His blessing instead of wearing myself out chasing more."},{"id":"proverbs-10-3","ref":"Proverbs 10:3","kjv":"The LORD will not suffer the soul of the righteous to famish: but he casteth away the substance of the wicked.","say":"Because I am counted righteous in Christ, the LORD will not suffer my soul to famish.","theme":"provision-finances","when":"doing right but struggling","mean":"God pledges not to let the righteous starve, so remaining faithful is never the losing path, even when the season feels lean."},{"id":"proverbs-11-25","ref":"Proverbs 11:25","kjv":"The liberal soul shall be made fat: and he that watereth shall be watered also himself.","say":"As a liberal soul I am made fat; and as I water others, I am watered also myself.","theme":"provision-finances","when":"generosity, sowing into others","mean":"Generosity is never a net loss; the hand that refreshes others is itself refreshed by God. So I give freely, trusting Him to replenish me."},{"id":"proverbs-13-22","ref":"Proverbs 13:22","kjv":"A good man leaveth an inheritance to his children’s children: and the wealth of the sinner is laid up for the just.","say":"As a good man, I leave an inheritance to my children's children.","theme":"provision-finances","when":"planning for family; legacy","mean":"Godly stewardship looks past my own lifetime to provide for generations, so I plan and steward faithfully rather than squander what passes through my hands."},{"id":"proverbs-3-9-10","ref":"Proverbs 3:9-10","kjv":"Honour the LORD with thy substance, and with the firstfruits of all thine increase: So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.","say":"I honour the LORD with my substance and with the firstfruits of all my increase, and He fills my barns with plenty.","theme":"provision-finances","when":"firstfruits; a giving decision","mean":"When I put God first with my resources, ahead of everything else, He takes responsibility to provide; the firstfruits are His, and honouring Him comes before increase."},{"id":"psalm-128-2","ref":"Psalms 128:2","kjv":"For thou shalt eat the labour of thine hands: happy shalt thou be, and it shall be well with thee.","say":"I eat the labour of my hands; happy am I, and it is well with me.","theme":"provision-finances","when":"weary at honest work","mean":"For the one who fears the LORD and walks in His ways (Ps 128:1), honest labour is rewarded with the joy of eating its own fruit; so my work is not wasted and I may enjoy its reward with gladness."},{"id":"psalm-145-16","ref":"Psalms 145:16","kjv":"Thou openest thine hand, and satisfiest the desire of every living thing.","say":"The LORD opens His hand and satisfies my desire, as He satisfies the desire of every living thing.","theme":"provision-finances","when":"unmet needs, discontent","mean":"The same open hand that feeds all creation in due season is open toward me; I bring my needs to Him and trust Him to satisfy as a good Provider."},{"id":"psalm-84-11","ref":"Psalms 84:11","kjv":"For the LORD God is a sun and shield: the LORD will give grace and glory: no good thing will he withhold from them that walk uprightly.","say":"The LORD God is my sun and shield; as I walk uprightly before Him, no good thing will He withhold from me.","theme":"provision-finances","when":"disappointment, feeling withheld from","mean":"As I walk honestly before God, He withholds nothing that is truly good for me, so I can trust even His 'no' and His timing as part of His goodness."},{"id":"psalms-23-1","ref":"Psalms 23:1","kjv":"The LORD is my shepherd; I shall not want.","say":"The LORD is my shepherd; I shall not want.","theme":"provision-finances","when":"anxious, feeling the lack","mean":"With the LORD shepherding me I lack no truly necessary thing, so my security rests in His care, not in my bank balance."},{"id":"psalms-34-10","ref":"Psalms 34:10","kjv":"The young lions do lack, and suffer hunger: but they that seek the LORD shall not want any good thing.","say":"Because I seek the LORD, I shall not want any good thing.","theme":"provision-finances","when":"fear of missing out, lack","mean":"Even strong young lions go hungry, but those who seek the LORD are not denied any genuinely good thing He knows I need."},{"id":"2-timothy-1-9","ref":"2 Timothy 1:9","kjv":"Who hath saved us, and called us with an holy calling, not according to our works, but according to his own purpose and grace, which was given us in Christ Jesus before the world began,","say":"God has saved me and called me with a holy calling, not according to my works, but according to His own purpose and grace in Christ Jesus.","theme":"purpose-calling","when":"when you feel unworthy of your calling","mean":"My calling rests on God's purpose and grace rather than my performance, so I walk in it with humble confidence in Him."},{"id":"2-timothy-4-7","ref":"2 Timothy 4:7","kjv":"I have fought a good fight, I have finished my course, I have kept the faith:","say":"By grace I fight the good fight, I finish my course, and I keep the faith all the way to the end.","theme":"purpose-calling","when":"running low near the finish","mean":"My aim is not only to start well but to fight, finish, and stay faithful, so I press on to complete the course God gave me."},{"id":"acts-20-24","ref":"Acts 20:24","kjv":"But none of these things move me, neither count I my life dear unto myself, so that I might finish my course with joy, and the ministry, which I have received of the Lord Jesus, to testify the gospel of the grace of God.","say":"None of these things move me; I count not my life dear to myself, that I may finish my course with joy and the ministry I received of the Lord Jesus.","theme":"purpose-calling","when":"under pressure or opposition in your work","mean":"Like Paul, I refuse to let hardship stop me, keeping my eyes on finishing the course and ministry the Lord entrusted to me."},{"id":"esther-4-14","ref":"Esther 4:14","kjv":"For if thou altogether holdest thy peace at this time, then shall there enlargement and deliverance arise to the Jews from another place; but thou and thy father’s house shall be destroyed: and who knoweth whether thou art come to the kingdom for such a time as this?","say":"By God's providence I have come to my place for such a time as this; He positioned me here on purpose, and I rise to meet the moment He prepared me for.","theme":"purpose-calling","when":"facing a daunting God-given opportunity","mean":"My present position is no accident but a providential appointment, so I step up courageously into the moment God prepared for me."},{"id":"isaiah-43-7","ref":"Isaiah 43:7","kjv":"Even every one that is called by my name: for I have created him for my glory, I have formed him; yea, I have made him.","say":"I am called by God's name; He created me for His glory, He formed me, yea, He made me.","theme":"purpose-calling","when":"searching for the point of your life","mean":"God made and formed me for His glory, so the ultimate aim of my life is to display and honour Him."},{"id":"jeremiah-1-5","ref":"Jeremiah 1:5","kjv":"Before I formed thee in the belly I knew thee; and before thou camest forth out of the womb I sanctified thee, and I ordained thee a prophet unto the nations.","say":"Before I was formed in the womb God knew me; before I came forth He sanctified me and ordained me for the purpose He appointed.","theme":"purpose-calling","when":"doubting you were made for anything","mean":"God knew and set me apart before I was born, so my purpose rests on His eternal choice, not my qualifications."},{"id":"john-15-16","ref":"John 15:16","kjv":"Ye have not chosen me, but I have chosen you, and ordained you, that ye should go and bring forth fruit, and that your fruit should remain: that whatsoever ye shall ask of the Father in my name, he may give it you.","say":"Jesus has chosen me and ordained me to go and bring forth fruit, and my fruit shall remain.","theme":"purpose-calling","when":"wondering whether my work will last","mean":"Christ Himself appointed me to bear lasting fruit, so I serve from His choosing of me, not from striving to prove myself."},{"id":"philippians-1-6","ref":"Philippians 1:6","kjv":"Being confident of this very thing, that he which hath begun a good work in you will perform it until the day of Jesus Christ:","say":"I am confident of this very thing: He who has begun a good work in me will perform it until the day of Jesus Christ.","theme":"purpose-calling","when":"feeling unfinished or stuck","mean":"God started the good work in me and takes responsibility to complete it, so I rest in His faithfulness to finish what He began."},{"id":"philippians-3-14","ref":"Philippians 3:14","kjv":"I press toward the mark for the prize of the high calling of God in Christ Jesus.","say":"Forgetting what is behind, I press toward the mark for the prize of the high calling of God in Christ Jesus.","theme":"purpose-calling","when":"tempted to quit or look back","mean":"There is a finish line and a prize in my calling, so I lean forward and keep moving toward it rather than dwelling on the past."},{"id":"proverbs-19-21","ref":"Proverbs 19:21","kjv":"There are many devices in a man’s heart; nevertheless the counsel of the LORD, that shall stand.","say":"Many are the devices in my heart, but the counsel of the LORD for my life shall stand.","theme":"purpose-calling","when":"facing a big decision or detour","mean":"My own plans are many and uncertain, but God's counsel prevails, so I submit my plans to His sure purpose."},{"id":"psalm-138-8","ref":"Psalms 138:8","kjv":"The LORD will perfect that which concerneth me: thy mercy, O LORD, endureth for ever: forsake not the works of thine own hands.","say":"The LORD will perfect that which concerns me; His mercy endures for ever, and He will not forsake the work of His own hands.","theme":"purpose-calling","when":"anxious about an unfinished assignment","mean":"God personally completes what concerns my life because I am the work of His hands, so I trust Him to see His purpose through."},{"id":"psalm-57-2","ref":"Psalms 57:2","kjv":"I will cry unto God most high; unto God that performeth all things for me.","say":"I cry unto God most high, unto God who performs all things for me and brings His purpose for my life to completion.","theme":"purpose-calling","when":"when the assignment feels bigger than you","mean":"I depend on the Most High who accomplishes all He has purposed for me, so I pray and lean on Him to perform His plan."},{"id":"romans-11-29","ref":"Romans 11:29","kjv":"For the gifts and calling of God are without repentance.","say":"The gifts and calling of God are without repentance; He will not take back what He has placed in me.","theme":"purpose-calling","when":"when I feel disqualified by failure","mean":"God does not regret or withdraw the gifts and calling He gave, so past failure does not cancel my assignment."},{"id":"romans-8-28","ref":"Romans 8:28","kjv":"And we know that all things work together for good to them that love God, to them who are the called according to his purpose.","say":"Because I love God and am called according to His purpose, I trust that all things are working together for my good.","theme":"purpose-calling","when":"when life feels like it is falling apart","mean":"Because I belong to God's purpose, even hard things are being woven together for good, so I keep loving Him and stay in His call."},{"id":"1-corinthians-13-5","ref":"1 Corinthians 13:5","kjv":"Doth not behave itself unseemly, seeketh not her own, is not easily provoked, thinketh no evil;","say":"The love in me is not easily provoked and thinks no evil.","theme":"relationships-forgiveness","when":"tempted to take offense","mean":"Real charity refuses to be touchy or to nurse suspicious, evil imaginations about people, so I let love steady my reactions instead of my irritation."},{"id":"1-john-4-20","ref":"1 John 4:20","kjv":"If a man say, I love God, and hateth his brother, he is a liar: for he that loveth not his brother whom he hath seen, how can he love God whom he hath not seen?","say":"Because I love God whom I have not seen, I will not hate my brother whom I have seen; I love him too.","theme":"relationships-forgiveness","when":"checking my own heart","mean":"Love for God I cannot see is proven real by love for people I can see; harbored hatred would expose a hollow faith, so I refuse to carry it."},{"id":"1-peter-4-8","ref":"1 Peter 4:8","kjv":"And above all things have fervent charity among yourselves: for charity shall cover the multitude of sins.","say":"Above all things I keep fervent charity toward others, for charity shall cover the multitude of sins.","theme":"relationships-forgiveness","when":"others' faults wearing on me","mean":"Earnest, warm love is my top priority with people, and it chooses to cover and overlook many faults rather than expose and multiply them."},{"id":"colossians-3-13","ref":"Colossians 3:13","kjv":"Forbearing one another, and forgiving one another, if any man have a quarrel against any: even as Christ forgave you, so also do ye.","say":"I forbear with others and forgive anyone I have a quarrel against; even as Christ forgave me, so also do I.","theme":"relationships-forgiveness","when":"an old grudge","mean":"When I have a real complaint against someone, I choose to bear with them and let it go, patterning my pardon after Christ's pardon of me."},{"id":"ephesians-4-32","ref":"Ephesians 4:32","kjv":"And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ’s sake hath forgiven you.","say":"I am kind and tenderhearted toward others, forgiving them even as God for Christ's sake has forgiven me.","theme":"relationships-forgiveness","when":"someone hurt me","mean":"My forgiveness of others is measured by the forgiveness God already poured out on me in Christ, so I release the one who wronged me."},{"id":"galatians-6-2","ref":"Galatians 6:2","kjv":"Bear ye one another’s burdens, and so fulfil the law of Christ.","say":"I bear the burdens of others, and so fulfil the law of Christ.","theme":"relationships-forgiveness","when":"someone around me is struggling","mean":"Love in action means shouldering the heavy loads others carry, and in doing so I fulfill the law of Christ."},{"id":"genesis-50-20","ref":"Genesis 50:20","kjv":"But as for you, ye thought evil against me; but God meant it unto good, to bring to pass, as it is this day, to save much people alive.","say":"What others meant for evil against me, God means unto good; like Joseph, I forgive and refuse to take God's place as judge.","theme":"relationships-forgiveness","when":"betrayed by family or those close to me","mean":"Joseph forgave the brothers who sold him because he trusted that God had overruled their evil for good; this frees me to release deep, personal betrayal to a sovereign God who redeems what was meant to harm me."},{"id":"hebrews-12-14","ref":"Hebrews 12:14","kjv":"Follow peace with all men, and holiness, without which no man shall see the Lord:","say":"I follow peace with all men, and holiness, that I may see the Lord.","theme":"relationships-forgiveness","when":"pursuing reconciliation","mean":"Peace with others and personal holiness are things I actively pursue rather than wait for, and holiness is the condition for seeing the Lord."},{"id":"john-13-34","ref":"John 13:34","kjv":"A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.","say":"By the new commandment of my Lord, I love others even as Christ has loved me.","theme":"relationships-forgiveness","when":"my daily walk with people","mean":"Loving one another is a direct command of Jesus, and His own love for me is the standard and source from which I love others."},{"id":"leviticus-19-18","ref":"Leviticus 19:18","kjv":"Thou shalt not avenge, nor bear any grudge against the children of thy people, but thou shalt love thy neighbour as thyself: I am the LORD.","say":"I take no vengeance and bear no grudge, but love my neighbour as myself, for the LORD is my God.","theme":"relationships-forgiveness","when":"tempted to get even","mean":"God forbids revenge and grudge-holding and commands neighbor-love, the very command Jesus affirmed, so I leave justice to Him and treat others as I would be treated."},{"id":"luke-6-27","ref":"Luke 6:27","kjv":"But I say unto you which hear, Love your enemies, do good to them which hate you,","say":"I love my enemies and do good to those who hate me, because Jesus told me to.","theme":"relationships-forgiveness","when":"someone opposing me","mean":"The love Christ commands reaches past friends to active enemies, turning even hatred against me into an occasion to do them concrete good."},{"id":"mark-11-25","ref":"Mark 11:25","kjv":"And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses.","say":"When I stand praying, I forgive whatever I have against any, that my Father in heaven may forgive me my trespasses.","theme":"relationships-forgiveness","when":"praying with a grievance","mean":"Before I bring my requests to God I lay down every offense I carry, so that unforgiveness does not block the prayer or the pardon I seek."},{"id":"matthew-18-22","ref":"Matthew 18:22","kjv":"Jesus saith unto him, I say not unto thee, Until seven times: but, Until seventy times seven.","say":"I forgive not just seven times, but until seventy times seven, as my Lord commanded.","theme":"relationships-forgiveness","when":"repeated offense","mean":"Christ removes the ceiling on forgiveness, so when someone sins against me again I keep extending mercy rather than counting and cutting them off."},{"id":"matthew-6-14","ref":"Matthew 6:14","kjv":"For if ye forgive men their trespasses, your heavenly Father will also forgive you:","say":"I forgive others their trespasses, and so my heavenly Father also forgives me.","theme":"relationships-forgiveness","when":"needing to let go to pray free","mean":"Jesus ties my willingness to forgive others directly to the Father's forgiveness of me, so I keep my own account clear by releasing theirs."},{"id":"proverbs-10-12","ref":"Proverbs 10:12","kjv":"Hatred stirreth up strifes: but love covereth all sins.","say":"I will not let hatred stir up strife; my love covers all offenses.","theme":"relationships-forgiveness","when":"tempted to stir up or feed conflict","mean":"Hatred keeps conflict churning, but love does the opposite by covering offenses, so I choose the peacemaking path that quiets strife instead of fueling it."},{"id":"proverbs-17-9","ref":"Proverbs 17:9","kjv":"He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.","say":"I cover a transgression and seek love; I will not keep repeating a matter that separates friends.","theme":"relationships-forgiveness","when":"tempted to rehash an old offense","mean":"Bringing up an old wrong again and again drives close friends apart, so I protect the relationship by covering the fault rather than rehearsing it."},{"id":"romans-12-18","ref":"Romans 12:18","kjv":"If it be possible, as much as lieth in you, live peaceably with all men.","say":"As much as lieth in me, I live peaceably with all men.","theme":"relationships-forgiveness","when":"tension with someone","mean":"I own my side of the peace, doing all that is within my power to be reconciled, even when the other person's response is beyond my control."},{"id":"romans-12-21","ref":"Romans 12:21","kjv":"Be not overcome of evil, but overcome evil with good.","say":"I am not overcome of evil, but I overcome evil with good.","theme":"relationships-forgiveness","when":"tempted to repay a wrong","mean":"I refuse to let someone else's evil pull me into retaliation; set in the passage on not avenging oneself, I conquer evil by answering with deliberate good."},{"id":"1-john-4-4","ref":"1 John 4:4","kjv":"Ye are of God, little children, and have overcome them: because greater is he that is in you, than he that is in the world.","say":"I am of God, and I have overcome the spirits of error, because greater is He that is in me than he that is in the world.","theme":"spiritual-warfare","when":"facing opposition","mean":"The Spirit living in me is greater than every spirit of error in the world, so the outcome of any spiritual contest is settled by who dwells within me, not by how strong the opposition looks."},{"id":"1-peter-5-9","ref":"1 Peter 5:9","kjv":"Whom resist stedfast in the faith, knowing that the same afflictions are accomplished in your brethren that are in the world.","say":"I resist my adversary, stedfast in the faith, knowing my brethren throughout the world endure the same afflictions.","theme":"spiritual-warfare","when":"under relentless pressure from the enemy","mean":"I meet my adversary with steady, unwavering faith, strengthened to know believers across the world are enduring the very same afflictions."},{"id":"2-corinthians-10-4","ref":"2 Corinthians 10:4","kjv":"(For the weapons of our warfare are not carnal, but mighty through God to the pulling down of strong holds;)","say":"The weapons of my warfare are not carnal, but mighty through God to the pulling down of strongholds.","theme":"spiritual-warfare","when":"facing a stronghold that will not break","mean":"My real battles are spiritual, not fleshly, and the weapons God gives are mighty enough to pull down every stronghold set against me."},{"id":"colossians-2-15","ref":"Colossians 2:15","kjv":"And having spoiled principalities and powers, he made a shew of them openly, triumphing over them in it.","say":"Christ has spoiled principalities and powers and made an open show of them, triumphing over them; so I stand in His victory.","theme":"spiritual-warfare","when":"oppressed by dark powers","mean":"At the cross Jesus publicly disarmed and defeated every hostile power, so I stand against them not to win a victory but from a victory He has already openly secured."},{"id":"deuteronomy-20-4","ref":"Deuteronomy 20:4","kjv":"For the LORD your God is he that goeth with you, to fight for you against your enemies, to save you.","say":"The LORD my God goes with me, to fight for me against my enemies and to save me.","theme":"spiritual-warfare","when":"afraid before a battle","mean":"I never face my enemies alone; the LORD my God Himself goes with me to fight for me and to save me, and that settles my courage."},{"id":"ephesians-6-10","ref":"Ephesians 6:10","kjv":"Finally, my brethren, be strong in the Lord, and in the power of his might.","say":"I am strong in the Lord, and in the power of His might.","theme":"spiritual-warfare","when":"spiritual warfare","mean":"My strength to stand against spiritual opposition is borrowed from the Lord's own might, put on like armour, not mustered from within myself."},{"id":"ephesians-6-11","ref":"Ephesians 6:11","kjv":"Put on the whole armour of God, that ye may be able to stand against the wiles of the devil.","say":"I put on the whole armour of God, so that I can stand against the wiles of the devil.","theme":"spiritual-warfare","when":"under spiritual attack","mean":"My standing against the enemy rests on God's provision, not my own strength; clothed in His full armour I can hold my ground against every scheme of the devil."},{"id":"ephesians-6-13","ref":"Ephesians 6:13","kjv":"Wherefore take unto you the whole armour of God, that ye may be able to withstand in the evil day, and having done all, to stand.","say":"I have taken up the whole armour of God, that I may withstand in the evil day, and having done all, I stand.","theme":"spiritual-warfare","when":"under spiritual attack, the evil day","mean":"When the pressure is at its worst, the victory is sometimes simply to remain standing; armed in God I do everything I can and then hold my ground rather than retreat."},{"id":"james-4-7","ref":"James 4:7","kjv":"Submit yourselves therefore to God. Resist the devil, and he will flee from you.","say":"I submit myself to God; I resist the devil, and he flees from me.","theme":"spiritual-warfare","when":"under spiritual attack","mean":"Submission to God comes first; from that place of surrender my resistance has real authority, and the enemy must flee rather than dominate me."},{"id":"luke-10-19","ref":"Luke 10:19","kjv":"Behold, I give unto you power to tread on serpents and scorpions, and over all the power of the enemy: and nothing shall by any means hurt you.","say":"In Jesus' name I have authority to tread on serpents and scorpions and over all the power of the enemy, and nothing shall by any means hurt me.","theme":"spiritual-warfare","when":"spiritual attack","mean":"Jesus delegates His authority over every power of the enemy, so I stand against the devil's schemes in His name, confident no scheme can finally harm my soul — this is spiritual authority, not a promise of bodily invincibility."},{"id":"revelation-12-11","ref":"Revelation 12:11","kjv":"And they overcame him by the blood of the Lamb, and by the word of their testimony; and they loved not their lives unto the death.","say":"I overcome the accuser by the blood of the Lamb and by the word of my testimony, and I love not my life unto the death.","theme":"spiritual-warfare","when":"accused and condemned","mean":"The enemy accuses, but I answer him with the finished blood of Jesus and my spoken testimony of what Christ has done, holding to Him above my own comfort and even my life."},{"id":"romans-16-20","ref":"Romans 16:20","kjv":"And the God of peace shall bruise Satan under your feet shortly. The grace of our Lord Jesus Christ be with you. Amen.","say":"The God of peace shall bruise Satan under my feet shortly, and the grace of my Lord Jesus Christ is with me.","theme":"spiritual-warfare","when":"harassed by the enemy","mean":"The God of peace Himself will crush the enemy under His people's feet, so the victory is His doing on His timing, and I wait in the grace of Jesus rather than fighting in my own might."},{"id":"2-corinthians-12-9","ref":"2 Corinthians 12:9","kjv":"And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.","say":"His grace is sufficient for me, for His strength is made perfect in my weakness; therefore I gladly glory in my infirmities, that the power of Christ may rest upon me.","theme":"strength-renewal","when":"weakness / limitation","mean":"God left Paul's thorn in place so Christ's power could rest on him, which means my unremoved weaknesses become the very place His strength is displayed."},{"id":"colossians-1-11","ref":"Colossians 1:11","kjv":"Strengthened with all might, according to his glorious power, unto all patience and longsuffering with joyfulness;","say":"I am strengthened with all might, according to His glorious power, unto all patience and longsuffering with joyfulness.","theme":"strength-renewal","when":"needing endurance / patience","mean":"The strength Paul prays for here is aimed at patient endurance with joy, so God's power in me shows up as the grace to keep going kindly under prolonged strain."},{"id":"deuteronomy-33-25","ref":"Deuteronomy 33:25","kjv":"Thy shoes shall be iron and brass; and as thy days, so shall thy strength be.","say":"As my days are, so shall my strength be; my God supplies strength to match each day I face.","theme":"strength-renewal","when":"daily demands / the long haul","mean":"Moses' blessing on Asher promises strength matched to each day, so I trust God to supply for today's load rather than collapse under tomorrow's imagined weight."},{"id":"ephesians-3-16","ref":"Ephesians 3:16","kjv":"That he would grant you, according to the riches of his glory, to be strengthened with might by his Spirit in the inner man;","say":"According to the riches of His glory, I am strengthened with might by His Spirit in the inner man.","theme":"strength-renewal","when":"spiritually depleted / inner weakness","mean":"Paul prays for inward strengthening by the Spirit so Christ dwells at home in the heart, which means my deepest reserves are resupplied from God's glory, not my willpower."},{"id":"exodus-15-2","ref":"Exodus 15:2","kjv":"The LORD is my strength and song, and he is become my salvation: he is my God, and I will prepare him an habitation; my father’s God, and I will exalt him.","say":"The LORD is my strength and my song, and He is become my salvation; He is my God, and I will exalt Him.","theme":"strength-renewal","when":"after deliverance / testimony","mean":"Israel sang this at the Red Sea, turning a rescue into worship, teaching me to name the LORD as my strength and give Him the praise after He delivers me."},{"id":"habakkuk-3-19","ref":"Habakkuk 3:19","kjv":"The LORD God is my strength, and he will make my feet like hinds’ feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments.","say":"The LORD God is my strength; He makes my feet like hinds' feet, and makes me to walk upon my high places.","theme":"strength-renewal","when":"rough / uncertain season","mean":"Even when provision fails, God gives me sure-footedness over dangerous heights, so I keep climbing steadily through hard terrain by His strength."},{"id":"isaiah-40-29","ref":"Isaiah 40:29","kjv":"He giveth power to the faint; and to them that have no might he increaseth strength.","say":"When I am faint, He gives me power; when I have no might, He increases my strength.","theme":"strength-renewal","when":"faint / no strength left","mean":"God's help meets me precisely at the point of empty, so my weakness qualifies me for His supply rather than disqualifying me."},{"id":"isaiah-40-31","ref":"Isaiah 40:31","kjv":"But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.","say":"Because I wait upon the LORD, He renews my strength; I mount up with wings as eagles, I run and am not weary, I walk and do not faint.","theme":"strength-renewal","when":"exhausted, burned out, weary","mean":"Waiting on the LORD exchanges my exhaustion for His renewed strength, so I draw my endurance from Him instead of running on empty."},{"id":"isaiah-58-11","ref":"Isaiah 58:11","kjv":"And the LORD shall guide thee continually, and satisfy thy soul in drought, and make fat thy bones: and thou shalt be like a watered garden, and like a spring of water, whose waters fail not.","say":"The LORD guides me continually and satisfies my soul in drought; by His unfailing spring I am like a watered garden whose waters never fail.","theme":"strength-renewal","when":"burnout and inward dryness","mean":"Even in a drought season God keeps me watered from within, so my renewal and strength flow from His unfailing spring, not from my circumstances."},{"id":"nehemiah-8-10","ref":"Nehemiah 8:10","kjv":"Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength.","say":"I will not be grieved, for the joy of the LORD is my strength.","theme":"strength-renewal","when":"grieving / discouraged","mean":"Joy in the LORD, not my circumstances, is what upholds me, so I refuse to be overcome by sorrow and lean on that joy for strength."},{"id":"philippians-4-13","ref":"Philippians 4:13","kjv":"I can do all things through Christ which strengtheneth me.","say":"I can do all things through Christ which strengtheneth me.","theme":"strength-renewal","when":"facing a hard task","mean":"In context Paul had learned contentment in plenty and in want, so this is Christ's strength to endure and obey in every circumstance, not a blank cheque for my own ambitions."},{"id":"psalm-138-3","ref":"Psalms 138:3","kjv":"In the day when I cried thou answeredst me, and strengthenedst me with strength in my soul.","say":"In the day when I cry, He answers me, and strengthens me with strength in my soul.","theme":"strength-renewal","when":"crying out in prayer","mean":"The answer to his cry was inner strength, reminding me that when I pray God often reinforces my soul before He changes my circumstances."},{"id":"psalm-23-3","ref":"Psalms 23:3","kjv":"He restoreth my soul: he leadeth me in the paths of righteousness for his name’s sake.","say":"The Lord restoreth my soul and leadeth me in the paths of righteousness for his name's sake.","theme":"strength-renewal","when":"burned out","mean":"My Shepherd personally revives my inner life and guides me back onto right paths, so I trust Him to lead even when I am depleted."},{"id":"psalm-28-7","ref":"Psalms 28:7","kjv":"The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.","say":"The LORD is my strength and my shield; my heart trusts in Him and I am helped; therefore my heart greatly rejoiceth, and with my song I praise Him.","theme":"strength-renewal","when":"needing help / protection","mean":"Strength and protection come as I actually trust Him, and the help He gives turns into rejoicing and song rather than mere relief."},{"id":"psalm-73-26","ref":"Psalms 73:26","kjv":"My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.","say":"Though my flesh and my heart may fail, God is the strength of my heart and my portion for ever.","theme":"strength-renewal","when":"failing health / aging","mean":"Even as my body and emotions give way, God remains the lasting strength within me and the inheritance that outlives my frailty."},{"id":"psalms-103-5","ref":"Psalms 103:5","kjv":"Who satisfieth thy mouth with good things; so that thy youth is renewed like the eagle’s.","say":"The LORD satisfies my mouth with good things, so that my youth is renewed like the eagle's.","theme":"strength-renewal","when":"feeling aged, worn out, or depleted","mean":"God renews my vitality as I feed on His goodness, so I expect genuine refreshing even when I feel past my strength."},{"id":"zechariah-4-6","ref":"Zechariah 4:6","kjv":"Then he answered and spake unto me, saying, This is the word of the LORD unto Zerubbabel, saying, Not by might, nor by power, but by my spirit, saith the LORD of hosts.","say":"Not by my might, nor by my power, but by His Spirit, saith the LORD of hosts; so the work before me is accomplished by His Spirit and not my own strength.","theme":"strength-renewal","when":"trying in my own strength","mean":"Zerubbabel's mountain of a task would be finished by God's Spirit and not by human force, freeing me to lean on the Spirit instead of grinding away in my own power."},{"id":"1-chronicles-16-34","ref":"1 Chronicles 16:34","kjv":"O give thanks unto the LORD; for he is good; for his mercy endureth for ever.","say":"I give thanks unto the LORD, for He is good; and His mercy endureth for ever.","theme":"thankfulness-praise","when":"needing assurance of God's goodness","mean":"I thank God for who He is, good and everlastingly merciful, a truth that stands firm no matter how I feel."},{"id":"1-thessalonians-5-16","ref":"1 Thessalonians 5:16","kjv":"Rejoice evermore.","say":"I rejoice evermore.","theme":"thankfulness-praise","when":"discouraged, downcast","mean":"My joy is anchored in the unchanging Lord, so I can rejoice continually even when my circumstances give me no reason to."},{"id":"1-thessalonians-5-18","ref":"1 Thessalonians 5:18","kjv":"In every thing give thanks: for this is the will of God in Christ Jesus concerning you.","say":"In every thing I give thanks, for this is the will of God in Christ Jesus concerning me.","theme":"thankfulness-praise","when":"hard, unwanted circumstances","mean":"I give thanks in all things (not for the evil itself), because gratitude inside God's will keeps my heart anchored in Him whatever comes."},{"id":"colossians-3-17","ref":"Colossians 3:17","kjv":"And whatsoever ye do in word or deed, do all in the name of the Lord Jesus, giving thanks to God and the Father by him.","say":"Whatsoever I do in word or deed, I do all in the name of the Lord Jesus, giving thanks to God the Father by Him.","theme":"thankfulness-praise","when":"ordinary work and daily tasks","mean":"Every word and task becomes worship when done in Jesus' name with thanks, so no part of my day is too small to glorify God."},{"id":"daniel-2-23","ref":"Daniel 2:23","kjv":"I thank thee, and praise thee, O thou God of my fathers, who hast given me wisdom and might, and hast made known unto me now what we desired of thee: for thou hast now made known unto us the king’s matter.","say":"I thank Thee and praise Thee, O God of my fathers, for Thou hast given me wisdom and might, and made known to me what I asked of Thee.","theme":"thankfulness-praise","when":"God answered and gave needed wisdom","mean":"When God grants insight or breakthrough, I return thanks and credit to Him rather than taking it as my own cleverness."},{"id":"ephesians-5-20","ref":"Ephesians 5:20","kjv":"Giving thanks always for all things unto God and the Father in the name of our Lord Jesus Christ;","say":"I give thanks always for all things unto God and the Father, in the name of my Lord Jesus Christ.","theme":"thankfulness-praise","when":"bitterness, strained relationships","mean":"A thankful heart in Jesus' name guards me from bitterness and keeps me yielded to God in every area of life."},{"id":"habakkuk-3-17-18","ref":"Habakkuk 3:17-18","kjv":"Although the fig tree shall not blossom, neither shall fruit be in the vines; the labour of the olive shall fail, and the fields shall yield no meat; the flock shall be cut off from the fold, and there shall be no herd in the stalls: Yet I will rejoice in the LORD, I will joy in the God of my salvation.","say":"Though the fig tree does not blossom and the fields yield no meat, yet will I rejoice in the LORD; I will joy in the God of my salvation.","theme":"thankfulness-praise","when":"financial loss, barren season","mean":"Even when every visible resource fails, my joy rests in God Himself as my salvation and not in what I possess."},{"id":"hebrews-13-15","ref":"Hebrews 13:15","kjv":"By him therefore let us offer the sacrifice of praise to God continually, that is, the fruit of our lips giving thanks to his name.","say":"By Him I offer the sacrifice of praise to God continually, the fruit of my lips giving thanks to His name.","theme":"thankfulness-praise","when":"praising when I don't feel like it","mean":"Praise can cost me something, so I offer it through Christ as a deliberate sacrifice of faith, not merely a feeling."},{"id":"psalm-100-4","ref":"Psalms 100:4","kjv":"Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.","say":"I enter into His gates with thanksgiving, and into His courts with praise; I am thankful unto Him and bless His name.","theme":"thankfulness-praise","when":"beginning prayer or worship","mean":"Thanksgiving is the doorway into God's presence, so I come to Him with gratitude and not only with requests."},{"id":"psalm-103-1-2","ref":"Psalms 103:1-2","kjv":"Bless the LORD, O my soul: and all that is within me, bless his holy name. Bless the LORD, O my soul, and forget not all his benefits:","say":"Bless the LORD, O my soul, and all that is within me, bless His holy name; I will not forget all His benefits.","theme":"thankfulness-praise","when":"spiritually flat, forgetful","mean":"I stir up my own soul to worship and deliberately recall God's kindnesses rather than taking them for granted."},{"id":"psalm-118-24","ref":"Psalms 118:24","kjv":"This is the day which the LORD hath made; we will rejoice and be glad in it.","say":"This is the day which the LORD hath made; I will rejoice and be glad in it.","theme":"thankfulness-praise","when":"dreading the day ahead","mean":"Today is God's own gift and handiwork, so I choose gladness in it rather than letting dread rob the day He gave."},{"id":"psalm-150-6","ref":"Psalms 150:6","kjv":"Let every thing that hath breath praise the LORD. Praise ye the LORD.","say":"As long as I have breath, I will praise the LORD; let every thing that hath breath praise Him.","theme":"thankfulness-praise","when":"grateful simply to be alive","mean":"My very breath is both reason and means to praise, so as long as God gives me life I will use it to honor Him."},{"id":"psalm-34-1","ref":"Psalms 34:1","kjv":"I will bless the LORD at all times: his praise shall continually be in my mouth.","say":"I will bless the LORD at all times; His praise shall continually be in my mouth.","theme":"thankfulness-praise","when":"tempted to complain","mean":"Praising God is a settled decision, not a mood, so I keep blessing Him in every season instead of only when things go well."},{"id":"psalm-40-3","ref":"Psalms 40:3","kjv":"And he hath put a new song in my mouth, even praise unto our God: many shall see it, and fear, and shall trust in the LORD.","say":"God has put a new song in my mouth, even praise unto my God; many shall see it, and fear, and shall trust in the LORD.","theme":"thankfulness-praise","when":"coming out of a pit or depression","mean":"God replaces mourning with fresh praise, and my restored life becomes a testimony that draws others to trust Him."},{"id":"psalm-92-1","ref":"Psalms 92:1","kjv":"It is a good thing to give thanks unto the LORD, and to sing praises unto thy name, O most High:","say":"It is a good thing to give thanks unto the LORD, and to sing praises unto Thy name, O Most High.","theme":"thankfulness-praise","when":"weary morning routine","mean":"Thanksgiving is genuinely good for me; it lifts my soul to the Most High and reorders my whole day around Him."},{"id":"psalm-95-2","ref":"Psalms 95:2","kjv":"Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms.","say":"I come before His presence with thanksgiving, and make a joyful noise unto Him with psalms.","theme":"thankfulness-praise","when":"entering corporate worship","mean":"I draw near to God gladly and aloud, letting thanksgiving and song set the tone of my worship."},{"id":"psalms-68-19","ref":"Psalms 68:19","kjv":"Blessed be the Lord, who daily loadeth us with benefits, even the God of our salvation. Selah.","say":"Blessed be the Lord, who daily loadeth me with benefits, even the God of my salvation.","theme":"thankfulness-praise","when":"weary, carrying daily burdens","mean":"Every single day God piles mercies on me, so I pause to bless Him and notice His benefits rather than only counting what is missing."},{"id":"1-corinthians-15-57","ref":"1 Corinthians 15:57","kjv":"But thanks be to God, which giveth us the victory through our Lord Jesus Christ.","say":"Thanks be to God, who gives me the victory through my Lord Jesus Christ.","theme":"victory-authority","when":"facing fear of death","mean":"The victory over sin, death, and the grave is a gift God gives through Jesus, so I receive it with thanksgiving rather than earn it."},{"id":"1-john-5-4","ref":"1 John 5:4","kjv":"For whatsoever is born of God overcometh the world: and this is the victory that overcometh the world, even our faith.","say":"Because I am born of God, I overcome the world; and this is the victory that overcomes the world, even my faith.","theme":"victory-authority","when":"pressured by the world","mean":"New birth plants an overcoming life in me, and the instrument of that overcoming is simple faith in Christ, so I conquer the world's pull not by willpower but by trusting Him."},{"id":"1-john-5-5","ref":"1 John 5:5","kjv":"Who is he that overcometh the world, but he that believeth that Jesus is the Son of God?","say":"I overcome the world, because I believe that Jesus is the Son of God.","theme":"victory-authority","when":"wrestling with doubt","mean":"Scripture defines the overcomer simply as the one who believes Jesus is the Son of God, so my victory rests on the object of my faith rather than the strength of my feelings, and I hold to who He is when doubt rises."},{"id":"2-chronicles-20-15","ref":"2 Chronicles 20:15","kjv":"And he said, Hearken ye, all Judah, and ye inhabitants of Jerusalem, and thou king Jehoshaphat, Thus saith the LORD unto you, Be not afraid nor dismayed by reason of this great multitude; for the battle is not yours, but God’s.","say":"I will not be afraid nor dismayed by reason of this great multitude, for the battle is not mine, but God's.","theme":"victory-authority","when":"a battle too big","mean":"When the opposition is far larger than my strength, I hand the fight to God as the one whose battle it truly is, refusing fear because the responsibility and the outcome rest on Him."},{"id":"2-corinthians-2-14","ref":"2 Corinthians 2:14","kjv":"Now thanks be unto God, which always causeth us to triumph in Christ, and maketh manifest the savour of his knowledge by us in every place.","say":"Thanks be to God, who always causes me to triumph in Christ and makes manifest the fragrance of His knowledge through me in every place.","theme":"victory-authority","when":"feeling defeated","mean":"God leads me in Christ's triumphal procession as one already His, so even days that feel like loss become places where He spreads the fragrance of knowing Him through my life."},{"id":"isaiah-54-17","ref":"Isaiah 54:17","kjv":"No weapon that is formed against thee shall prosper; and every tongue that shall rise against thee in judgment thou shalt condemn. This is the heritage of the servants of the LORD, and their righteousness is of me, saith the LORD.","say":"No weapon that is formed against me shall prosper, and every tongue that rises against me in judgment I shall condemn; this is my heritage as a servant of the LORD, and my righteousness is of Him.","theme":"victory-authority","when":"slandered and attacked","mean":"Weapons may still be formed and tongues still rise, but none will ultimately prosper, because God guarantees this as the heritage of His servants whose righteousness comes from Him, not from their own record."},{"id":"philippians-2-10","ref":"Philippians 2:10","kjv":"That at the name of Jesus every knee should bow, of things in heaven, and things in earth, and things under the earth;","say":"At the name of Jesus every knee shall bow, things in heaven, things in earth, and things under the earth.","theme":"victory-authority","when":"standing on the authority of Jesus' name","mean":"Jesus is exalted above every realm, so when I stand and pray in His name I rest on the highest authority there is."},{"id":"psalm-110-1","ref":"Psalms 110:1","kjv":"The LORD said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.","say":"My Lord is seated at the right hand of God until His enemies are made His footstool, and in Him I am seated also.","theme":"victory-authority","when":"facing opposition or enemies","mean":"Because Christ already reigns at God's right hand and I am seated in Him (Ephesians 2:6), I meet every opposition from under His finished authority, awaiting the day all is put beneath His feet."},{"id":"psalm-18-39","ref":"Psalms 18:39","kjv":"For thou hast girded me with strength unto the battle: thou hast subdued under me those that rose up against me.","say":"The LORD has girded me with strength unto the battle and subdued under me those that rose up against me.","theme":"victory-authority","when":"feeling weak before a fight","mean":"The strength I need for the battle is clothing God Himself puts on me, and it is He who subdues the opposition, so I enter conflict dressed in His supply rather than my own weakness."},{"id":"psalm-60-12","ref":"Psalms 60:12","kjv":"Through God we shall do valiantly: for he it is that shall tread down our enemies.","say":"Through God I shall do valiantly, for it is He who shall tread down my enemies.","theme":"victory-authority","when":"needing courage","mean":"Real courage and effectiveness come through God working in and with me, and it is He, not my own bravado, who finally tramples down what rises against me."},{"id":"revelation-3-21","ref":"Revelation 3:21","kjv":"To him that overcometh will I grant to sit with me in my throne, even as I also overcame, and am set down with my Father in his throne.","say":"Because I overcome, Christ grants me to sit with Him in His throne, even as He also overcame and is set down with His Father.","theme":"victory-authority","when":"weary, needing to endure","mean":"Overcoming is a call to endure to the end, and the promised reward is to share Christ's own throne, so I press on patterned after the One who already overcame and is seated with the Father."},{"id":"romans-5-17","ref":"Romans 5:17","kjv":"For if by one man’s offence death reigned by one; much more they which receive abundance of grace and of the gift of righteousness shall reign in life by one, Jesus Christ.)","say":"I have received the abundance of grace and the gift of righteousness, and I reign in life by One, Jesus Christ.","theme":"victory-authority","when":"dominated by circumstances","mean":"Grace gives me a righteousness I did not produce, and it lifts me from being ruled by sin and circumstance to reigning in life through Christ, so I live from His throne, not under my troubles."},{"id":"romans-8-37","ref":"Romans 8:37","kjv":"Nay, in all these things we are more than conquerors through him that loved us.","say":"In all these things I am more than a conqueror through Christ who loved me.","theme":"victory-authority","when":"overwhelmed by trials","mean":"Victory is not escaping hardship but overcoming in the middle of it, carried by the love of Christ rather than my own strength."},{"id":"daniel-2-21","ref":"Daniel 2:21","kjv":"And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding:","say":"My God changes the times and the seasons; He gives wisdom to the wise and knowledge to those who know understanding, and I look to Him for wisdom.","theme":"wisdom-guidance","when":"facing a hard problem","mean":"The same God who governs history and nations gives wisdom to those who seek it, so I bring my hardest problems to the One who holds the whole picture."},{"id":"ephesians-1-17","ref":"Ephesians 1:17","kjv":"That the God of our Lord Jesus Christ, the Father of glory, may give unto you the spirit of wisdom and revelation in the knowledge of him:","say":"The God of my Lord Jesus Christ, the Father of glory, gives me the spirit of wisdom and revelation in the knowledge of Him.","theme":"wisdom-guidance","when":"wanting to know God more","mean":"The deepest wisdom is knowing God Himself, and He gives His Spirit to reveal Him; so I pursue true wisdom by pursuing Him."},{"id":"isaiah-30-21","ref":"Isaiah 30:21","kjv":"And thine ears shall hear a word behind thee, saying, This is the way, walk ye in it, when ye turn to the right hand, and when ye turn to the left.","say":"My ears hear His word behind me saying, This is the way, walk in it, whether I turn to the right hand or to the left.","theme":"wisdom-guidance","when":"uncertain which path to take","mean":"As I follow God, He promises to correct and direct my course step by step so I can know the right way to walk."},{"id":"james-1-5","ref":"James 1:5","kjv":"If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.","say":"When I lack wisdom, I ask of my God, who giveth to all men liberally and upbraideth not; and He gives it to me without finding fault.","theme":"wisdom-guidance","when":"I don't know what to do","mean":"God welcomes my honest request for wisdom and gives it generously without scolding me for needing to ask, so I can ask boldly and expect Him to answer."},{"id":"james-3-17","ref":"James 3:17","kjv":"But the wisdom that is from above is first pure, then peaceable, gentle, and easy to be intreated, full of mercy and good fruits, without partiality, and without hypocrisy.","say":"The wisdom God gives me from above is pure, peaceable, gentle, easy to be intreated, full of mercy and good fruits, without partiality and without hypocrisy.","theme":"wisdom-guidance","when":"handling a tense relationship","mean":"God's wisdom shows itself not in cleverness but in a pure, peace-loving, merciful character, so I ask Him for the kind of wisdom that makes peace rather than strife."},{"id":"jeremiah-33-3","ref":"Jeremiah 33:3","kjv":"Call unto me, and I will answer thee, and shew thee great and mighty things, which thou knowest not.","say":"When I call upon the LORD, He answers me and shows me great and mighty things I do not know.","theme":"wisdom-guidance","when":"needing answers","mean":"God invites me to call on Him, and He promises both to answer and to reveal things beyond my own knowing, so I bring Him the matters that baffle me and wait for His light."},{"id":"john-16-13","ref":"John 16:13","kjv":"Howbeit when he, the Spirit of truth, is come, he will guide you into all truth: for he shall not speak of himself; but whatsoever he shall hear, that shall he speak: and he will shew you things to come.","say":"The Spirit of truth lives in me and guides me into all truth.","theme":"wisdom-guidance","when":"needing discernment","mean":"The Holy Spirit's own work is to lead me into truth, so I depend on Him to make God's reality clear to me."},{"id":"proverbs-16-9","ref":"Proverbs 16:9","kjv":"A man’s heart deviseth his way: but the LORD directeth his steps.","say":"I devise my way in my heart, but I trust the LORD to direct my steps.","theme":"wisdom-guidance","when":"making plans","mean":"I am free to plan, yet I hold my plans loosely, because God is the One who orders my actual steps; so I submit my planning to His direction."},{"id":"proverbs-2-6","ref":"Proverbs 2:6","kjv":"For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.","say":"The LORD gives me wisdom; out of His mouth come knowledge and understanding.","theme":"wisdom-guidance","when":"seeking understanding","mean":"Wisdom originates with God and flows from His word, so I seek Him and His word as the true source of knowledge and understanding."},{"id":"proverbs-3-5-6","ref":"Proverbs 3:5-6","kjv":"Trust in the LORD with all thine heart; and lean not unto thine own understanding. In all thy ways acknowledge him, and he shall direct thy paths.","say":"I trust in the LORD with all my heart and lean not on my own understanding; in all my ways I acknowledge Him, and He directs my paths.","theme":"wisdom-guidance","when":"facing a big decision","mean":"When I surrender my own reasoning and submit every area of my life to God, He takes responsibility to straighten and direct the road ahead of me."},{"id":"proverbs-8-14","ref":"Proverbs 8:14","kjv":"Counsel is mine, and sound wisdom: I am understanding; I have strength.","say":"God's counsel and sound wisdom are mine to receive; in Him are understanding and strength for what I face.","theme":"wisdom-guidance","when":"needing good counsel","mean":"True counsel and sound wisdom belong to God, so I look to Him rather than to my own cleverness for understanding and strength."},{"id":"psalm-143-10","ref":"Psalms 143:10","kjv":"Teach me to do thy will; for thou art my God: thy spirit is good; lead me into the land of uprightness.","say":"Teach me to do Your will, for You are my God; Your Spirit is good; lead me into the land of uprightness.","theme":"wisdom-guidance","when":"wanting God's will","mean":"I ask God not merely for answers but to teach me to actually do His will, trusting His good Spirit to lead me into upright living."},{"id":"psalm-25-9","ref":"Psalms 25:9","kjv":"The meek will he guide in judgment: and the meek will he teach his way.","say":"Because I walk humbly before God, He guides me in judgment and teaches me His way.","theme":"wisdom-guidance","when":"staying humble and teachable","mean":"God's guidance is promised to the humble and teachable, so I keep a lowly, yielded heart and trust Him to direct my judgment."},{"id":"psalm-32-8","ref":"Psalms 32:8","kjv":"I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.","say":"The LORD instructs me and teaches me in the way I should go, and He guides me with His eye upon me.","theme":"wisdom-guidance","when":"needing direction","mean":"God Himself promises to personally teach me and keep His watchful eye on my steps, so I am never left to figure out life's direction alone."},{"id":"psalm-48-14","ref":"Psalms 48:14","kjv":"For this God is our God for ever and ever: he will be our guide even unto death.","say":"This God is my God for ever and ever, and He will be my guide even unto death.","theme":"wisdom-guidance","when":"facing an unknown future","mean":"The God I serve never stops guiding me; His leadership covers my whole life right to the end, so I am never without a guide."},{"id":"psalm-73-24","ref":"Psalms 73:24","kjv":"Thou shalt guide me with thy counsel, and afterward receive me to glory.","say":"You guide me with Your counsel, and afterward You will receive me to glory.","theme":"wisdom-guidance","when":"planning the road ahead","mean":"God counsels me through this life and promises glory at the end, so my present guidance and my eternal destiny are both safe in His hands."},{"id":"1-corinthians-10-31","ref":"1 Corinthians 10:31","kjv":"Whether therefore ye eat, or drink, or whatsoever ye do, do all to the glory of God.","say":"Whether I eat or drink, or whatsoever I do, I do all to the glory of God.","theme":"work-excellence","when":"ordinary daily duties","mean":"Even the smallest task becomes worship when my aim is God's glory, so nothing I do is wasted or beneath purpose."},{"id":"1-corinthians-15-58","ref":"1 Corinthians 15:58","kjv":"Therefore, my beloved brethren, be ye stedfast, unmoveable, always abounding in the work of the Lord, forasmuch as ye know that your labour is not in vain in the Lord.","say":"I am stedfast, unmoveable, always abounding in the work of the Lord, for my labour is not in vain in the Lord.","theme":"work-excellence","when":"when work feels pointless","mean":"Because I labour in the Lord, my work is never wasted; He sees it and it counts, so I stay steady and keep going."},{"id":"colossians-3-23","ref":"Colossians 3:23","kjv":"And whatsoever ye do, do it heartily, as to the Lord, and not unto men;","say":"Whatsoever I do, I do it heartily, as to the Lord, and not unto men.","theme":"work-excellence","when":"any task, offered as worship","mean":"My true Master is the Lord, so I pour my whole heart into every task and let my labour itself become an offering of worship to Him."},{"id":"colossians-3-24","ref":"Colossians 3:24","kjv":"Knowing that of the Lord ye shall receive the reward of the inheritance: for ye serve the Lord Christ.","say":"I serve the Lord Christ, and of the Lord I shall receive the reward of the inheritance.","theme":"work-excellence","when":"overlooked or under-rewarded at work","mean":"Even when people underpay or overlook me, my true reward comes from Christ whom I ultimately serve; so I keep working faithfully, eyes on the inheritance."},{"id":"daniel-6-3","ref":"Daniel 6:3","kjv":"Then this Daniel was preferred above the presidents and princes, because an excellent spirit was in him; and the king thought to set him over the whole realm.","say":"An excellent spirit is in me, and I do my work with integrity and excellence.","theme":"work-excellence","when":"working under scrutiny","mean":"Like Daniel, a Spirit-given excellence and faithfulness mark my work, so I serve diligently under watchful eyes."},{"id":"ecclesiastes-9-10","ref":"Ecclesiastes 9:10","kjv":"Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest.","say":"Whatsoever my hand finds to do, I do it with my might.","theme":"work-excellence","when":"a mundane or hard task","mean":"I give my full strength to whatever is in front of me today, because this short life is my window to work heartily while I can."},{"id":"ephesians-6-7","ref":"Ephesians 6:7","kjv":"With good will doing service, as to the Lord, and not to men:","say":"With good will I do my service, as to the Lord, and not to men.","theme":"work-excellence","when":"a boss who doesn't notice","mean":"I serve with a willing heart as though Christ were my employer, so my diligence never depends on human recognition."},{"id":"exodus-31-3","ref":"Exodus 31:3","kjv":"And I have filled him with the spirit of God, in wisdom, and in understanding, and in knowledge, and in all manner of workmanship,","say":"God fills me with His Spirit — with wisdom, understanding, and knowledge for all manner of my work.","theme":"work-excellence","when":"a skilled craft or project","mean":"Like Bezaleel, real skill is a gift of the Spirit of God, so I lean on Him for the craftsmanship my work requires."},{"id":"nehemiah-6-3","ref":"Nehemiah 6:3","kjv":"And I sent messengers unto them, saying, I am doing a great work, so that I cannot come down: why should the work cease, whilst I leave it, and come down to you?","say":"I am doing a great work, so I cannot come down; I will not let distraction stop what God has given me to build.","theme":"work-excellence","when":"resisting distraction","mean":"Like Nehemiah on the wall, I treat my God-given assignment as great and guard it from the distractions that would pull me away."},{"id":"proverbs-12-24","ref":"Proverbs 12:24","kjv":"The hand of the diligent shall bear rule: but the slothful shall be under tribute.","say":"The hand of the diligent bears rule; so my diligence lifts me to lead, not to lag.","theme":"work-excellence","when":"tempted to coast","mean":"Faithful diligence tends toward responsibility and leadership, while slackness forfeits it; so I choose to work diligently."},{"id":"proverbs-16-3","ref":"Proverbs 16:3","kjv":"Commit thy works unto the LORD, and thy thoughts shall be established.","say":"I commit my works unto the LORD, and my thoughts are established.","theme":"work-excellence","when":"planning a project","mean":"When I surrender my work and plans to God, He steadies my thinking and brings my purposes to pass in line with His will."},{"id":"proverbs-22-29","ref":"Proverbs 22:29","kjv":"Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men.","say":"Because I am diligent in my business, I shall stand before kings, and not before mean men.","theme":"work-excellence","when":"growing in a craft or career","mean":"Honed, faithful diligence tends to open doors into greater rooms; so I keep sharpening my craft and trust God to position me."},{"id":"psalm-75-6-7","ref":"Psalms 75:6-7","kjv":"For promotion cometh neither from the east, nor from the west, nor from the south. But God is the judge: he putteth down one, and setteth up another.","say":"My promotion comes not from men but from God, who alone puts down one and sets up another.","theme":"work-excellence","when":"overlooked for promotion","mean":"Advancement is God's to give, so I work faithfully and trust Him rather than office politics to lift me up."},{"id":"psalm-90-17","ref":"Psalms 90:17","kjv":"And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.","say":"The beauty of the Lord my God is upon me; He establishes the work of my hands.","theme":"work-excellence","when":"wanting lasting results","mean":"I ask God to rest His favour on me and make my labour fruitful and enduring, because only what He establishes truly lasts."},{"id":"romans-12-11","ref":"Romans 12:11","kjv":"Not slothful in business; fervent in spirit; serving the Lord;","say":"I am not slothful in business; I am fervent in spirit, serving the Lord.","theme":"work-excellence","when":"feeling unmotivated","mean":"I bring spiritual fervour to my daily work, serving the Lord Himself through it rather than dragging my feet."}];
window.HEIR_PLAN=[{"month":1,"title":"January — Who I Am in Christ","focus":"Lay the foundation of the whole year by declaring, again and again, the brand-new identity I have been given in Christ.","themeKeys":["identity-in-christ"]},{"month":2,"title":"February — Anchored in God's Love & Presence","focus":"Stand on that identity by resting in how completely God loves me and how near He stays every single moment.","themeKeys":["gods-love","gods-presence","identity-in-christ"]},{"month":3,"title":"March — Victory, Authority & Spiritual Warfare","focus":"Rise up in the authority Christ won for me and overcome every scheme of the enemy and every pull of sin.","themeKeys":["victory-authority","spiritual-warfare","holiness-victory-over-sin"]},{"month":4,"title":"April — Protected, Kept & at Peace","focus":"Settle under God's covering so fear and anxiety lose their grip and His peace guards my heart and mind.","themeKeys":["protection-safety","peace-anxiety","gods-presence"]},{"month":5,"title":"May — Provision & Excellence at Work","focus":"Declare God's abundant provision and His favor, excellence, and blessing on the work of my hands.","themeKeys":["provision-finances","work-excellence"]},{"month":6,"title":"June — Marriage, Parenting & Household","focus":"Speak God's covenant blessing over my marriage, my children, and the whole atmosphere of my home.","themeKeys":["marriage","parenting"]},{"month":7,"title":"July — Relationships & Forgiveness","focus":"Walk in love toward others, release every offense quickly, and keep my relationships whole and healthy.","themeKeys":["relationships-forgiveness","gods-love"]},{"month":8,"title":"August — Health, Healing & Renewed Strength","focus":"Receive God's healing and let Him renew my strength in body, soul, and spirit for all that lies ahead.","themeKeys":["health-healing","strength-renewal"]},{"month":9,"title":"September — Wisdom, Guidance & Purpose","focus":"Seek God's wisdom for every decision and step with confidence into the purpose He is calling me to.","themeKeys":["wisdom-guidance","purpose-calling"]},{"month":10,"title":"October — Perseverance, Waiting & Hope","focus":"Hold fast through the waiting seasons, anchored in hope and renewed strength until the promise comes.","themeKeys":["perseverance-waiting","comfort-hope","strength-renewal"]},{"month":11,"title":"November — Holiness, Wisdom & Thanksgiving","focus":"Finish the year's walk in holiness and wisdom, giving thanks for everything God has done in me.","themeKeys":["holiness-victory-over-sin","wisdom-guidance","thankfulness-praise"]},{"month":12,"title":"December — Faith, Prayer & Thanksgiving","focus":"End the year strong, believing God without wavering, praying boldly, and overflowing with praise.","themeKeys":["faith-trust","prayer","thankfulness-praise"]}];
